const TBE_TALENTS = [{"name":"Armor Piercer","category":"Combat","sub":false,"requires":"","rank":"per-skill","desc":"Pick one specific weapon type (shortsword, mace, 2H sword, etc.). Gain +1 Piercing when attacking with a weapon of this type. Can be purchased once per weapon type."},{"name":"Find The Gap","category":"Combat","sub":true,"requires":"Armor Piercer and a corresponding weapon skill of 80","rank":"once","desc":"You have a knack for finding the weak point in an opponent’s armor. Successful attacks with your Armor Piercer weapon always cause a minimum of a 1-pt wound, regardless of the target’s armor or shield. Requires Armor Piercer and a corresponding weapon skill of 80."},{"name":"Armor Training (I-IV)","category":"Combat","sub":false,"requires":"","rank":"once","desc":"Wearing heavier armor (Reinforced Leather, Mail, Scale, and Plate) on the Body or Arms prevents an untrained combatant from being able to use any Combat Maneuvers in a combat round. Armor Training allows regular use of Combat Maneuvers, but each new level must be acquired in order from lightest armor to heaviest: » armor training i allows Combat Maneuvers while wearing Body or Arm armor as heavy as Reinforced Leather. » armor training ii allows Combat Maneuvers while wearing Body or Arm armor as heavy as Mail. » armor training iii allows Combat Maneuvers while wearing Body or Arm armor as heavy as Scale. Edbert’s Previous Career was a Warrior, and so he starts with Armor Training III : he may wear Reinforced Leather, Mail, or Scale armor on his Body or Arms location without affecting his Combat Maneuvers. If he wanted to wear Plate Body or Arm armor and still be able to use Combat Maneuvers, he would have to acquire this Talent again ( Armor Training IV ). Arn, on the other hand, has taken this Talent only once ( Armor Training I ) and is therefore trained in Reinforced Leather only: if he wears Mail, Scale, or Plate in the Body or Arms, he will not be able to perform any Combat Maneuvers. Talents that say “Once per scene” last for the current situation, as decided by the GM. “Once per session” means once during the current play session. Combat talents that say “As your action this round” cannot combine their effects with each other or with other actions, such as Charging with a Sweeping Attack. The GM rules on edge cases. “Once per combat” refers to the current initiative sequence. Combat ends when the characters leave the initiative sequence, such as when all enemies are defeated or the party flees. » armor training iv allows Combat Maneuvers while wearing Body or Arm armor as heavy as Plate. An Ogre can take this Talent only once, gaining training in Bone armor only."},{"name":"Assassin","category":"Combat","sub":false,"requires":"","rank":"three","desc":"Gain +1 SL when attacking with surprise. Can be purchased up to three times."},{"name":"Catch And Release","category":"Combat","sub":false,"requires":"","rank":"once","desc":"If attacked with a thrown weapon and not surprised, you can attempt to catch it and immediately hurl it back at the attacker. You must have one free hand, or you may freely drop a held item (including a shield) to free one. As a defense, make an opposed Thrown roll against the attack. If you win, your DoS counts as a successful attack against the original attacker, using your roll to determine hit location. They may defend as normal. You may use this Talent only once per round."},{"name":"Cloak And Blade","category":"Combat","sub":false,"requires":"","rank":"once","desc":"Tical Dondallan duelists often use a cloak and blade in combat. When fighting with either a Light or Medium weapon while using a cloak instead of a shield, and wearing only Padding, Quilted, or Leather armor pieces, gain the following: +20 to parries, -1 SL to Disarm. Additionally, once per combat, at any point during your turn, you may Taunt Foe as a free action, using Perform instead of Intimidate or Wit ."},{"name":"Dance Of Blades","category":"Combat","sub":true,"requires":"Cloak and Blade","rank":"once","desc":"Once per combat, as an action, make a Perform roll to make a disorienting, dancing blur of cloak m ovements. Any SLs generated can be used as Favor for the duration of this combat. Requires Cloak and Blade ."},{"name":"Close The Distance","category":"Combat","sub":false,"requires":"","rank":"once","desc":"Any bonus from Reach weapons used against you is reduced by 10. They may still choose to use the Set for Charge action against you."},{"name":"Combat Awareness","category":"Combat","sub":false,"requires":"","rank":"five","desc":"Add +1 to your Initiative modifier. Can be purchased up to five times."},{"name":"Defender","category":"Combat","sub":false,"requires":"","rank":"once","desc":"Pick one specific melee weapon type (shortsword, mace, 2H sword, fists, etc.). Gain +10 when parrying with that weapon."},{"name":"Improved Defender","category":"Combat","sub":true,"requires":"and replaces Defender","rank":"once","desc":"As above, but gain +20 instead. Requires and replaces Defender ."},{"name":"Drop Attack","category":"Combat","sub":false,"requires":"","rank":"once","desc":"Once a round in melee combat, if you kill, knock Prone, or send your opponent into Shock, you may immediately make one free attack at -20 on an adjacent foe currently Engaged with you. The free attack cannot use any “as your action ” type of Talent."},{"name":"Cleave","category":"Combat","sub":true,"requires":"Drop Attack","rank":"once","desc":"As above, but without the -20 penalty. Requires Drop Attack ."},{"name":"Eagle Eye","category":"Combat","sub":false,"requires":"","rank":"once","desc":"Add one zone when determining effective range when using one specific ranged weapon type (longbow, sling, etc.)."},{"name":"Enhanced Defense","category":"Combat","sub":false,"requires":"","rank":"once","desc":"When defending with a specific Combat skill while outnumbered in melee, your opponents only get a +10 Outnumbering bonus. This Talent can be purchased once for each Combat skill."},{"name":"Great Defense","category":"Combat","sub":true,"requires":"Enhanced Defense","rank":"once","desc":"As above, but one primary opponent (you choose each round) gets no outnumbering bonus; the rest get +10. Requires Enhanced Defense ."},{"name":"Fast Runner","category":"Combat","sub":false,"requires":"","rank":"once","desc":"As your action, you may Run 2 zones instead of 1."},{"name":"Fast Skirmisher","category":"Combat","sub":false,"requires":"","rank":"once","desc":"If you get 20 or more on your Initiative result, you get two turns in the round: one on your Initiative result, and the next at your Initiative result -20 (for example, rolling “21 ” allows you to act on “21” and again on “1 ” ). You may act and move (if possible) on each turn within the round. Only one of your turns can be used for casting a spell or asking for a miracle. Cannot be used while mounted."},{"name":"Feint","category":"Combat","sub":false,"requires":"","rank":"once","desc":"As part of your melee attack action, you may make a Hard (-20) Deceive roll. If you succeed, you mislead your opponent, and he defends at -10. If you fail, your opponent sees your ruse and defends with +10 instead. Either way, he’ll see it coming next time: Feint can never be used twice in a row on the same opponent."},{"name":"Improved Feint","category":"Combat","sub":true,"requires":"and replaces Feint","rank":"once","desc":"As above, but with your successful Deceive , your opponent defends at -20. Requires and replaces Feint ."},{"name":"Forceful Shot","category":"Combat","sub":false,"requires":"","rank":"once","desc":"For 4 SLs, you may use the Drive Back Maneuver with a Missile weapon. This can knock a combatant out of an Engaged melee and into a neighboring zone."},{"name":"Full Quiver","category":"Combat","sub":false,"requires":"","rank":"once","desc":"Once per combat, you may re-roll an Ammo Supply Die."},{"name":"Hard-Headed","category":"Combat","sub":false,"requires":"","rank":"once","desc":"You do not become stunned from Head Impairment."},{"name":"Hold The Line","category":"Combat","sub":false,"requires":"","rank":"once","desc":"When you take the Stand Your Ground action, add +1 to your Toughness."},{"name":"Horse Archer","category":"Combat","sub":false,"requires":"","rank":"once","desc":"Your ranged attacks on horseback are not capped by your Ride skill."},{"name":"Impaired Fighter, Arm","category":"Combat","sub":false,"requires":"","rank":"once","desc":"If your Arm is rendered useless from impairment, and you are not in Shock, you can still use that arm to make Combat rolls at a -20 penalty."},{"name":"Impaired Fighter, Leg","category":"Combat","sub":false,"requires":"","rank":"once","desc":"If a Leg is impaired, and you are not in Shock, you may still take the Run action (but not the Charge action)."},{"name":"Intimidating Charge","category":"Combat","sub":false,"requires":"","rank":"once","desc":"A successful Charge attack frightens your foe. If the target fails a Willpower or Might roll (defender’s choice) opposed to your original attack roll, they must choose the Flee action on their next turn. Creatures larger than you get +20 per size category. You may only attempt this once per opponent per combat, and it must be declared before the Charge. Will not affect Mindless or Undead creatures, or any creature with Ferocity 5+."},{"name":"Knock-Out Strike","category":"Combat","sub":false,"requires":"","rank":"once","desc":"When damaging a target’s Head from behind and with surprise, they are rendered Unconscious and in Shock on any failed Wound Die result."},{"name":"Large Shield Training","category":"Combat","sub":false,"requires":"","rank":"once","desc":"Allows you to equip a Large shield (using 3 Weapon"},{"name":"Mounted Charge","category":"Combat","sub":false,"requires":"","rank":"once","desc":"When charging on horseback (or other applicable beast), gain +1 SL to any successful Charge attack."},{"name":"Overrun","category":"Combat","sub":true,"requires":"Mounted Charge","rank":"once","desc":"If your Mounted Charge attack is successful, you have access to the Overrun special Combat Maneuver. Requires Mounted Charge . » Overrun - 3 SLs. After a mounted charge, leave the Engagement and move back out to Close range, on the opposite side of the zone from where you came. You do not provoke any free attacks by doing so. You may not become Engaged with any new foes while moving."},{"name":"On Your Feet","category":"Combat","sub":false,"requires":"","rank":"once","desc":"Reduce any Rise from Prone penalties from Body armor by 10."},{"name":"Jump Up","category":"Combat","sub":true,"requires":"and replaces On Your Feet","rank":"once","desc":"Reduce any Rise from Prone penalties from Body armor by 20. Requires and replaces On Your Feet."},{"name":"Powerful Blow","category":"Combat","sub":false,"requires":"","rank":"per-skill","desc":"Pick one specific weapon type (shortsword, mace, 2H sword, longbow, fists, etc.). Do +1 base damage when using a weapon of this type. Can be purchased once per weapon type."},{"name":"Pugilist","category":"Combat","sub":false,"requires":"","rank":"once","desc":"When making a Might attack or defense roll versus an armed opponent, the penalty is reduced to -10 ."},{"name":"Advanced Pugilist","category":"Combat","sub":true,"requires":"and replaces Pugilist","rank":"once","desc":"When making a Might attack or defense roll versus an armed opponent, there is no penalty. Requires and replaces Pugilist."},{"name":"Quickdraw","category":"Combat","sub":false,"requires":"","rank":"per-skill","desc":"Choose one Combat skill. Drawing an “at hand” weapon (i.e., a weapon using up Weapon ENC) that uses this skill does not require an action. You may draw and attack without penalty. Can be purchased once per Combat skill."},{"name":"Rapid Fire","category":"Combat","sub":false,"requires":"","rank":"once","desc":"You can make a Ranged attack with a longbow, short bow, or throwing knives at two separate targets with the same ranged attack roll, made at -20. They must be within the same zone as one another, and they each defend separately against your roll. The general locations hit are the same on both targets by default. Any resulting Combat Maneuvers can be applied to one target only. Two Ammo Supply Die rolls must be made."},{"name":"Riposte","category":"Combat","sub":false,"requires":"","rank":"once","desc":"If you parry a successful melee attack and win the opposed roll with 3+ DoS, your melee attack against that opponent on your next turn, made with the weapon you parried with, is at +20."},{"name":"Rise A Fighter","category":"Combat","sub":false,"requires":"","rank":"once","desc":"You can Rise from Prone by rolling Endurance , Might , or Willpower (choose one when purchasing this Talent) instead of Athletics. RUN FOR YOUR LIFE! - When fleeing melee, gain +20 to your Athletics roll."},{"name":"Shield Wall","category":"Combat","sub":false,"requires":"","rank":"once","desc":"When two or more possessors of this Talent remain shoulder-to-shoulder with Medium or Large shields in the same zone, it costs +2 SL to use Circumvent Shield, Drive Back, or Trip Combat Maneuvers against them. If moving, they must move together on the same Initiative (likely using the Delay action) to maintain the wall. The wall also counts as cover to allies directly behind it."},{"name":"Speed-Loader","category":"Combat","sub":false,"requires":"","rank":"once","desc":"You may reload your crossbow as part of your action, provided you don’t move on your turn."},{"name":"Sweeping Attack","category":"Combat","sub":false,"requires":"","rank":"once","desc":"As your action this round, make a single melee attack with a Heavy weapon at -20 against two or more Engaged melee opponents. Roll once and apply to all foes, who may defend as normal. The locations hit are the same on all targets by default. Any resulting Combat Maneuvers are applied to one target only."},{"name":"Tactician","category":"Combat","sub":false,"requires":"","rank":"once","desc":"When Preparing the Battlefield, gain +2 SL to a successful roll."},{"name":"Master Tactician","category":"Combat","sub":true,"requires":"Tactician","rank":"once","desc":"When Preparing the Battlefield, gain +20 on your skill roll. Requires Tactician ."},{"name":"Tactical Advance","category":"Combat","sub":false,"requires":"","rank":"once","desc":"When advancing on someone who has made a Fighting Withdrawal, gain +20 on your defense against their attack."},{"name":"Tactical Retreat","category":"Combat","sub":false,"requires":"","rank":"three","desc":"When making a Fighting Withdrawal, you may make a single attack on one additional opponent who engages you. Can be purchased up to three times (to a maximum of four attacks on four different opponents)."},{"name":"Two-Weapon Fighter","category":"Combat","sub":false,"requires":"","rank":"once","desc":"If you are armed with a Light or Medium weapon in the primary hand, and a Light weapon in the secondary hand, you have access to a special Combat Maneuver when you attack with the weapon in your primary hand: » Secondary Attack - 3 SLs. Make an immediate -20 unopposed attack with your secondary weapon against any Engaged opponent. The secondary weapon adds +1 AP to all locations (and can be bypassed with Circumvent Shield), but does not count as a shield against ranged attacks. You do not suffer an additional -20 penalty for fighting with the off-hand."},{"name":"Two-Weapon Master","category":"Combat","sub":true,"requires":"Two-Weapon Fighter","rank":"once","desc":"Reduce the Secondary Attack modifier to -10. Requires Two-Weapon Fighter . Combat Maneuver Talents"},{"name":"Bullrush","category":"Combat","sub":false,"requires":"","rank":"once","desc":"Drive Back costs 1 less SL to perform when attacking with one chosen melee Combat skill."},{"name":"Disarming Hit","category":"Combat","sub":false,"requires":"","rank":"per-skill","desc":"Disarm costs 1 less SL to perform when attacking with one chosen Combat skill. Can be purchased once per Combat skill."},{"name":"Drop. Your. Sword.","category":"Combat","sub":false,"requires":"","rank":"per-skill","desc":"Compel Surrender costs 1 less SL to perform when attacking with one chosen Combat skill. Can be purchased once per Combat skill."},{"name":"Leg Sweeper","category":"Combat","sub":false,"requires":"","rank":"per-skill","desc":"Trip costs 1 less SL to perform when attacking with one chosen Combat skill. Can be purchased once per Combat skill."},{"name":"Precise Strike","category":"Combat","sub":false,"requires":"","rank":"per-skill","desc":"Choose Location costs one less SL when attacking with one chosen Combat skill. Can be purchased once per Combat skill."},{"name":"Shield Beat","category":"Combat","sub":false,"requires":"","rank":"once","desc":"Shield Bash costs 1 less SL to perform when attacking with one chosen size of shield (Buckler, Small, Medium, or Large). Can be purchased once per shield size."},{"name":"Shield Breaker","category":"Combat","sub":false,"requires":"","rank":"three","desc":"When using the Cleave Shield Maneuver of a 2H weapon, add +2 to the d20 roll. Can be purchased up to three times per 2H weapon."},{"name":"Shield Maneuver","category":"Combat","sub":false,"requires":"","rank":"per-skill","desc":"Circumvent Shield costs 1 less SL to perform when attacking with one chosen Combat skill. Can be purchased once per Combat skill."},{"name":"Subjugating Words","category":"Combat","sub":false,"requires":"","rank":"once","desc":"Use Intimidate as a Combat skill to force your enemy to give up. As your action, roll Intimidate vs your foe’s Combat skill. If you win with 3+ SL, you can Compel Surrender, subject to all the normal rules regarding Compel Surrender (target must be disadvantaged, etc). If you win with only 1 or 2 SLs, you Unbalance your foe with your intimidating approach."},{"name":"Wrestler","category":"Combat","sub":false,"requires":"","rank":"3","desc":"Grapple costs 1 less SL to perform when attacking with Might . Can be purchased once. Each of the following can be purchased up to 3 times:"},{"name":"Shield Arm","category":"Combat","sub":false,"requires":"","rank":"once","desc":"Any Circumvent Shield attempts made against you cost +1"},{"name":"Slippery","category":"Combat","sub":false,"requires":"","rank":"once","desc":"Any Grapple attempts made against you cost +1"},{"name":"Stable Stance","category":"Combat","sub":false,"requires":"","rank":"once","desc":"Any Trip or Shield Bash attempts made against you cost +1"},{"name":"Stay Put","category":"Combat","sub":false,"requires":"","rank":"once","desc":"Any Drive Back attempts made against you cost +1"},{"name":"Stay Up","category":"Combat","sub":false,"requires":"","rank":"once","desc":"Any Unbalance attempts made against you cost +1"},{"name":"Strong Grip","category":"Combat","sub":false,"requires":"","rank":"once","desc":"Any Disarm attempts made against you cost +1 SL."},{"name":"Anti-Venom Blood","category":"Adventuring","sub":false,"requires":"","rank":"three","desc":"Gain +20 on Endurance rolls against poison. “…BUT IT IS NOT THIS DAY!” - Once per session, you can make an Inspire roll to recover spent Resolve equal to 1+ (1 per 2 SLs). This Resolve may be split among the party, including yourself. This does not remove Fatigue. Can be purchased up to three times, each giving an additional use per session."},{"name":"Careful Rationing","category":"Adventuring","sub":false,"requires":"","rank":"three","desc":"Once per session, if you’re the Quartermaster, you can ignore up to 3 points of penalties from any source when rolling on the Fatigue table. Can be purchased up to three times, each giving an additional use per session."},{"name":"Ease Of Passage","category":"Adventuring","sub":false,"requires":"","rank":"three","desc":"Once per session, this character can allow each PC in the party to suffer one less Fatigue at the end of a Journey’s leg, after the Fatigue roll is made (or after a day’s travel on a HexMarch). A party cannot benefit from more than one character with this Talent. Can be purchased up to three times, each giving an additional use per session."},{"name":"Enduring Watch","category":"Adventuring","sub":false,"requires":"","rank":"once","desc":"If you kept watch during a rest, recover Fatigue as if you had not kept watch."},{"name":"Fearless","category":"Adventuring","sub":false,"requires":"","rank":"once","desc":"Gain +20 on Willpower rolls against fear."},{"name":"Mettle","category":"Adventuring","sub":false,"requires":"","rank":"once","desc":"Gain +20 on Endurance rolls to resist Body Impairment from the Wound Die."},{"name":"On Through The Night","category":"Adventuring","sub":false,"requires":"","rank":"three","desc":"Once per session, if you’re the Guide, you can do a forced march and not suffer the -5 to the next Fatigue roll. Can be purchased up to three times, each giving an additional use per session."},{"name":"Quick And Quiet","category":"Adventuring","sub":false,"requires":"","rank":"once","desc":"You can use the Run action even while using Stealth ."},{"name":"Ride Like The Wind","category":"Adventuring","sub":false,"requires":"","rank":"once","desc":"While mounted, make a Ride roll at -20 as part of your movement to move one extra zone in a round (3 zones instead of 2)."},{"name":"Ship's Gunner","category":"Adventuring","sub":false,"requires":"","rank":"once","desc":"In Naval Combat, you can support your ship’s Weapon skill with your Sail/ Boat skill (add double your Sail/Boat Score). If you are also the ship’s captain, you cannot use this Talent in the same round as using your Sail/Boat skill to support the ship’s Maneuvering skill."},{"name":"Spyglass","category":"Adventuring","sub":false,"requires":"","rank":"three","desc":"Once per session, if you’re the Scout, you may try to avoid the Event even if your Perception roll failed. Can be purchased up to three times, each giving an additional use per session."},{"name":"Useful Gear","category":"Adventuring","sub":false,"requires":"","rank":"once","desc":"When taking Fatigue on a Journey, you may take 1 less by rolling the Gear Supply Die. This is in addition to any Fatigue reduced from use of the Rations Die."},{"name":"Watchmaster","category":"Adventuring","sub":false,"requires":"","rank":"once","desc":"If you are the only one keeping watch while in camp, your Perception penalty is -10 instead of -30."},{"name":"Barbed Tongue","category":"Social","sub":false,"requires":"","rank":"once","desc":"This Talent is similar to the Taunt combat action, but is used in a Competitive Social Encounter. You land a verbal jab to demoralize an opponent within earshot. Pick one target on the opposing side. As your action this round, make an opposed Intimidate or Wit roll against the target’s Willpower . If you win (and if they can understand you), they or their side suffers -20 to their next Social roll. For every 3 DoS, increase the penalty by an additional -10. Each subsequent use of Barbed Tongue against the same target in the same encounter suffers a cumulative -20 to your Intimidate or Wit roll."},{"name":"Blather","category":"Social","sub":false,"requires":"","rank":"once","desc":"Spew a string of gobbledegook to confuse one target, in combat or otherwise. The target must be able to hear and understand you. As an action, make a Wit roll opposed to the target’s Insight. If you win, they suffer a -20 to their next roll. If you win by 5+ DoS, the target is flabbergasted by your blather, loses their next action, and may only defend. Each subsequent use of Blather against the same target in the same encounter suffers a cumulative -20 to your Wit roll."},{"name":"Entertaining","category":"Social","sub":false,"requires":"","rank":"once","desc":"Your first use of Perform or Wit in a Static Social Encounter does not count against Tolerance. In a Competitive Social Encounter, the first use instead gives a +20 skill bonus."},{"name":"Expressive","category":"Social","sub":false,"requires":"","rank":"once","desc":"Your Social skills are not capped by the language you are speaking."},{"name":"Fiery Words","category":"Social","sub":false,"requires":"","rank":"once","desc":"Your first use of Inspire or Intimidate in a Static Social Encounter does not count against Tolerance. In a Competitive Social Encounter, the first use instead gives a +20 skill bonus."},{"name":"Honeyed Words","category":"Social","sub":false,"requires":"","rank":"once","desc":"Your first use of Persuade or Seduce in a Static Social Encounter does not count against Tolerance. In a Competitive Social Encounter, the first use instead gives a +20 skill bonus."},{"name":"Inspirational","category":"Social","sub":false,"requires":"","rank":"once","desc":"When using the Inspire Ally action in combat, a success grants either one ally +20 to their next roll (instead of +10), or two allies +10 each. For every 3 SLs, you gain another +10 that may be given to any eligible ally."},{"name":"I See Your Mind","category":"Social","sub":false,"requires":"","rank":"once","desc":"If someone in your party gains leverage through an Insight roll during a Social Encounter, you may immediately spend 1 leverage to learn one of the NPC’s Special Reactions (GM’s choice). You can learn only one Special Reaction this way per encounter. You may also spend 3 leverage to reveal the NPC’s Tolerance."},{"name":"Natural Politician","category":"Social","sub":false,"requires":"","rank":"once","desc":"Your first use of Deceive or Protocol in a Static Social Encounter does not count against Tolerance. In a Competitive Social Encounter, the first use instead gives a +20 skill bonus."},{"name":"Press The Point","category":"Social","sub":false,"requires":"","rank":"once","desc":"Once per Social Encounter, you can use a skill for a third time in a row, or you can use a Social skill with an NPC even if that same skill just failed."},{"name":"Rally The Troops","category":"Social","sub":false,"requires":"","rank":"once","desc":"When in Mass Combat, make any Rally actions with a +20 bonus. When not in Mass Combat, if forces under your control and within the sound of your voice fail a morale or fear ( Willpower ) roll for any reason, as an action, make an Intimidate or Inspire roll. For every 2 SLs, one friendly unit recovers from their failed morale and rejoins the battle."},{"name":"Storm The Decks","category":"Social","sub":false,"requires":"","rank":"once","desc":"When leading a crew in a Naval Combat boarding action, you can support their Crew value with double your Inspire Score each round of hand-to-hand combat. You must participate in the boarding action and get into combat yourself to use this Talent."},{"name":"Universal Taunt","category":"Social","sub":false,"requires":"","rank":"once","desc":"When Taunting a Foe in combat, roll any appropriate Social skill (not limited to Intimidate and Wit )."},{"name":"Alchemist","category":"Lore","sub":false,"requires":"","rank":"once","desc":"When successfully creating alchemical potions, make 1d4 doses + 1 dose per 2 SLs (instead of 1d3 + 1 per 3 SLs)."},{"name":"Barterer","category":"Lore","sub":false,"requires":"","rank":"once","desc":"Use Commerce to make one attempt to adjust the value of a bought or sold item by +10% per SL (instead of per 2 SLs) up to a maximum of 50% (see & Haggling )."},{"name":"Battlefield Tactics","category":"Lore","sub":false,"requires":"Battle-wise Lore skill","rank":"once","desc":"Once per battle (see Appendix A: Mass Combat ), a Commander can roll Battle-wise to increase the Initiative values of friendly units. Each SL can increase one unit’s Initiative value by 1. This effect lasts throughout the battle. Requires Battle-wise Lore skill ."},{"name":"Beast Tamer","category":"Lore","sub":false,"requires":"","rank":"once","desc":"Use Naturewise to tame a mundane wild animal as an extended roll, with each roll taking one day. Most normal animals require 6 SLs to tame; more aggressive animals require 9 to 15 SLs, and will attack on any critically failed extended roll. Offers of food may provide a bonus to one or more of the rolls (GM discretion). A tamed animal is considered friendly towards the Beast Tamer and anyone he designates as friends. The tamed animal will follow the Beast Tamer’s simple commands on a successful Naturewise roll. It is not a pet, however, and will still behave according to its nature where appropriate. It can be commanded to fight, but it will not generally fight to the death. At any one time, a Beast Tamer can have tamed a maximum number of animals based on their Size and on the Beast Tamer’s Naturewise Score: A Naturewise Score is 1–4: up to 3 Small animals A Naturewise Score is 5–7: as above, plus up to 2 Medium animals A Naturewise Score is 8+: as above, plus up to 1 Large animal Taming an additional animal of a particular size category requires first releasing one of the currently tamed animals."},{"name":"Beast Speaker","category":"Lore","sub":true,"requires":"Beast Tamer","rank":"once","desc":"Choose up to three of your tamed animals. Through body language, vocalizations, or other nonverbal cues, the tamed animals can communicate simple ideas to you, but nothing more complicated than what would be expressed in short, simple sentences. Requires Beast Tamer ."},{"name":"Bedside Manner","category":"Lore","sub":false,"requires":"","rank":"once","desc":"Add 3× your Heal Score when tending to a character’s Recovery rolls."},{"name":"Extra Bandages","category":"Lore","sub":false,"requires":"","rank":"three","desc":"Once per game session, you may re-roll a failed Medical Supply roll. Can be purchased up to three times, each giving an additional use per session."},{"name":"It's All In The Mold","category":"Lore","sub":false,"requires":"","rank":"once","desc":"Gain +20 on Heal rolls to purge infected wounds."},{"name":"Kingsfoil","category":"Lore","sub":false,"requires":"a Medical Supply roll","rank":"3","desc":"Once per game session, at any point while on a Journey, you may attempt to purge an infection without having to change to Daily Time. Requires a Medical Supply roll. Can be purchased up to 3 times, each giving an additional attempt per session."},{"name":"Lecturer","category":"Lore","sub":false,"requires":"","rank":"once","desc":"Pick one of your custom -wise skills. You may use this skill in a Social Encounter."},{"name":"Literate","category":"Lore","sub":false,"requires":"","rank":"once","desc":"You can read and write any language you can speak."},{"name":"Travel Planner","category":"Lore","sub":false,"requires":"","rank":"once","desc":"If you participate in the Travel Lore roll and gain any number of SLs, the party earns 2 additional points of Favor."},{"name":"Master Craftsman","category":"Lore","sub":false,"requires":"","rank":"once","desc":"When crafting a new item with Craft: Practical/Artistic , for every 3 SLs you earn over the required SLs, you may improve it in one of the ways below to make it a masterwork item. Each option may be selected only once, and each selection increases the crafting cost by an amount in sp equal to the item’s listed price: A +5% to a skill applicable to the item’s use A +1 damage to a weapon A -1 to the cost of one weapon Combat Maneuver (Choose Location, Disarm, etc.), to a minimum Maneuver cost of 1 A +1 AP to a piece of armor A -1 to the ENC or Bulk, to a minimum ENC or Bulk of 1 A critical failure while trying to gain extra SLs over the required SLs ruins the item, and the material costs from trying to improve the item (as described above) are wasted."},{"name":"Legendary Craftsman","category":"Lore","sub":true,"requires":"Master Craftsman","rank":"once","desc":"As above, but each improvement can be chosen twice (for example, the skill bonus could be +10%, or armor Bulk could be reduced by 2, to a minimum of 1 Bulk). Requires Master Craftsman ."},{"name":"Natural Remedies","category":"Lore","sub":false,"requires":"","rank":"once","desc":"Gain +10 on any Naturewise or Survival attempts to find ingredients for a natural healing potion, and +10 on Craft: Practical attempts to brew it."},{"name":"Surgeon","category":"Lore","sub":false,"requires":"","rank":"once","desc":"Gain +20 on Heal rolls to perform an amputation."},{"name":"Weapon Of Faith","category":"Lore","sub":false,"requires":"a Divinity skill of 70 and to be a faithful adherent of a god (you do not require the Godbound Talent)","rank":"once","desc":"Once per combat, as an action, pray to your god, spend 1 Resolve, and make a Divinity roll. Any SLs generated can be used as Favor to your actions for the duration of this combat. Requires a Divinity skill of 70 and to be a faithful adherent of a god (you do not require the Godbound Talent)."},{"name":"Armor Of Faith","category":"Lore","sub":true,"requires":"Weapon of Faith","rank":"once","desc":"Your faith protects you from harm. Once per combat, as an action, pray to your god, spend 3 Resolve, and make a Divinity roll. Add 1 (+ 1 per 3 SLs) of AP to all locations for the duration of the combat. Requires Weapon of Faith."},{"name":"Armored Caster","category":"Magic","sub":false,"requires":"","rank":"three","desc":"You are trained to weave magic through the hindrance of armor. Reduce the Total Cost increase from your armor’s Initiative penalty by 3. Can be purchased up to three times."},{"name":"Divine Conduit","category":"Magic","sub":false,"requires":"","rank":"once","desc":"You can try to channel your god’s wisdom by allowing the deity to speak through you at (in)opportune times. There is a chance that what is spoken is helpful. Spend 1 Resolve and roll Piety ; every 3 SLs generated produces one useful piece of information. The information should be presented in some combination of metaphor, symbolism, and poetry (the gods rarely give a straight answer). Failing the roll, or using this Talent twice in the same day, causes the deity to provide unhelpful or obstructive information. Using this Talent doesn’t cost any Piety , only the 1 Resolve."},{"name":"Enchanter","category":"Magic","sub":false,"requires":"","rank":"once","desc":"When making Enchanted items, roll Arcana . Reduce the accrued Fraying points by 1 per 3 SLs (to a minimum of 1 Fraying point)."},{"name":"Enduring Caster (Bind)","category":"Magic","sub":false,"requires":"","rank":"three","desc":"Spend 1 less Resolve when choosing to Mitigate after the casting roll with a specific Bind skill. Can be purchased up to three times in total (not per Bind)."},{"name":"Faded Pattern","category":"Magic","sub":false,"requires":"","rank":"once","desc":"Allows a non-Spellweaver to cast magic within certain limitations; these folk are known as Fades. A Fade wasn’t born to the power, and they will never be as accomplished as a true Spellweaver; their magical presence imprints a more unstable outline on the Pattern of the Weave. The following rules apply to a Fade: A You may spend XP (or “rounding out” skill points in character creation) on Bind and Strand skills. A You may never have a value of more than 70 in any Bind skill. A Start with a total of 5 levels among any Strands of your choice. A Fade may never have more than 7 in any Strand. Fades are not limited by Thin Strands. A You may not choose Bind skills as Savvy skills. A As a Fade, you are even more susceptible to the Weave’s lashings: any casting roll that critically fails immediately accumulates 1 Fraying point, in addition to any other critical failure effects. A Upon becoming a Fade, the Weave imprints you with a True Name, as a Spellweaver. Special Restriction : Unlike other Talents, Faded Pattern requires 2 Talent selections if chosen during character creation. These must come from your starting allotment of Talents, including those granted by Previous Careers. If purchased later in play, this Talent costs 10 XP instead of 5."},{"name":"Fast Summoner","category":"Magic","sub":false,"requires":"","rank":"once","desc":"Drawing your summoning circle only takes 15 minutes."},{"name":"Forceful Strand (Strand)","category":"Magic","sub":false,"requires":"","rank":"three","desc":"Pick one Strand. For any spell you cast using this Strand, the target resists at -10. Can be purchased up to three times per Strand."},{"name":"Godbound","category":"Magic","sub":false,"requires":"","rank":"once","desc":"This Talent allows the character to select a chosen patron deity and acquire the Piety skill at a starting value of 30 (or to add 30 during character creation). The Piety value can never be more than 90 (although it can be temporarily raised through modifiers). At character creation, only Previous Career: Godbound may select this Talent. Purchasing this Talent after character creation costs 10"},{"name":"Patterned In The Weave","category":"Magic","sub":false,"requires":"","rank":"once","desc":"This Talent can only be chosen at character creation . True Spellweavers are born to the Pattern. One must possess this Talent to be a fully-fledged Spellweaver. Choose a True Name imprinted upon you by the Weave: this name must be in the language of your people, and can be used to magically target you using the Arcane Tether Range (see Magic ). Gain +5 to Max Resolve."},{"name":"Ritual Caster","category":"Magic","sub":false,"requires":"","rank":"three","desc":"All your ritual spell rolls gain a +10 bonus. Can be purchased up to three times."},{"name":"Strand Secret (Strand)","category":"Magic","sub":false,"requires":"","rank":"once","desc":"Gain a new Strand of your choice at a value of 1 (a Thin Strand costs 10"},{"name":"True Faith","category":"Magic","sub":false,"requires":"","rank":"three","desc":"Once per session, increase the quality of a granted divine miracle by one step (Lesser to Middle or Middle to Greater). Can be purchased up to three times, each giving an additional use per session."},{"name":"Unerring Bolt (Strand)","category":"Magic","sub":false,"requires":"","rank":"three","desc":"Pick one Strand. Your attack spells with that Strand do +1 damage. Can be purchased up to three times per Strand."},{"name":"Weave Resistant (Choose)","category":"Magic","sub":false,"requires":"","rank":"per-skill","desc":"Pick one skill. Gain +20 when using that skill to oppose magic. Can be purchased once per skill."},{"name":"Weave Shadow","category":"Magic","sub":false,"requires":"","rank":"five","desc":"Make all rolls on the Weave Reaction Table at -1. Can be purchased up to five times, for up to -5 on the table."},{"name":"Words Alone","category":"Magic","sub":false,"requires":"","rank":"once","desc":"Casting a spell normally requires at least one free hand. With this Talent, the caster can still attempt the spell if both hands are occupied (such as wielding a weapon and shield) or otherwise prevented from making gestures (such as having both arms Impaired), but at -20 to the Bind roll."},{"name":"Cat's Fall","category":"Miscellaneous","sub":false,"requires":"","rank":"once","desc":"When falling, roll Athletics . Reduce falling damage by the SLs. If it reduces the damage to zero, you do not go Prone."},{"name":"Fast Healer","category":"Miscellaneous","sub":false,"requires":"","rank":"once","desc":"Remove 1 extra Wound Point on a successful Recovery roll. This Talent can only be purchased once."},{"name":"Grit (Location)","category":"Miscellaneous","sub":false,"requires":"","rank":"once","desc":"In the specified hit location(s), you do not automatically drop in Shock until you suffer a third Impairment there. Each time this Talent is taken, choose one from: the Body, the Head, both Arms, or both Legs."},{"name":"I Have Just The Thing","category":"Miscellaneous","sub":false,"requires":"","rank":"three","desc":"Once per game session, you may re-roll a failed Gear Supply Die. Can be purchased up to three times, each giving an additional use per session."},{"name":"Inner Strength","category":"Miscellaneous","sub":false,"requires":"","rank":"once","desc":"Increase your Max Resolve by 1. Can be purchased multiple times to a maximum Resolve of 30."},{"name":"Not Today, Death","category":"Miscellaneous","sub":false,"requires":"","rank":"five","desc":"Increase your Death Threshold by 2; recalculate Lethality Level. Can be purchased up to five times."},{"name":"Savvy","category":"Miscellaneous","sub":false,"requires":"","rank":"once","desc":"Pick one skill and mark an “S ” next to it. When improving this skill with XP, increase the result by +1 (see vancement ).You may not buy Savvy twice for the same skill."},{"name":"Steely Thews","category":"Miscellaneous","sub":false,"requires":"","rank":"three","desc":"Once per game session, you may re-roll the Wound Die, keeping the more favorable result. Can be purchased up to three times, each giving an additional use per session."},{"name":"Strong Back","category":"Miscellaneous","sub":false,"requires":"","rank":"three","desc":"Increase your number of Inventory slots by 2. Can be purchased up to three times."},{"name":"Strong Immune System","category":"Miscellaneous","sub":false,"requires":"","rank":"three","desc":"Once per game session, you may re-roll the Infection Die, keeping the more favorable result. Can be purchased up to three times, each giving an additional use per session."},{"name":"Swift Rider","category":"Miscellaneous","sub":false,"requires":"","rank":"once","desc":"While traveling alone on horseback during a Journey, you suffer only a -2 Fatigue penalty for a Forced March instead of -5."},{"name":"Swift Company","category":"Miscellaneous","sub":true,"requires":"Swift Rider and Ride 80+","rank":"once","desc":"The benefit extends to your whole party. Requires Swift Rider and Ride 80+."},{"name":"Tough","category":"Miscellaneous","sub":false,"requires":"","rank":"three","desc":"Increase your Toughness by 1. Can be purchased up to three times."},{"name":"Unkillable","category":"Miscellaneous","sub":false,"requires":"","rank":"once","desc":"Increase your Lethality Level by 1. You may improve your Lethality Level this way a maximum of three times."},{"name":"Weapon Belt","category":"Miscellaneous","sub":false,"requires":"","rank":"three","desc":"Increase your Max Weapon ENC by 1. Can be purchased up to three times."},{"name":"Blood-Fury","category":"Non-Human","sub":false,"requires":"","rank":"once","desc":"Half-Orc only . Any time your total Wound points exceed half your Death Threshold, you may choose to spend 3 Resolve to enter a Blood-fury state. For a number of rounds equal to half your Endurance Score (round up), gain +20 to any melee attack roll and +1 damage on successful attacks. However, you suffer -20 to all other skills during this time—including all defense rolls—and cannot retreat or disengage unless you succeed on a Willpower roll."},{"name":"Dwarven Swordsinger","category":"Non-Human","sub":false,"requires":"","rank":"once","desc":"Dwarf only. You are a Dwarven smith whose song can enchant a weapon that you forge (Master Craftsman improvements may be added during forging if desired). Once per turn of the moon (one month), you can make a Perform roll, taking 1 hour. You may instead Perform the song in 1 round, but at a -20 penalty. For every Perform SL, the weapon counts as magical for 1 day (as per the 1 SL Enhance Weapon Effect; see Chapter 14 - Weave Magic)."},{"name":"Devouring Maw","category":"Non-Human","sub":false,"requires":"","rank":"once","desc":"Ogre only. Your bite may be used as a Natural Weapon attack (2 dmg, Piercing 1). Once per scene, if you deal at least 1 Wound with this attack, you may consume the flesh to regain 1d3 Resolve (if the target is living) or 1 Resolve (if recently dead)."},{"name":"Whispered Inheritance","category":"Non-Human","sub":false,"requires":"","rank":"once","desc":"Bolg Fiir only. Once per session, you may roll Willpower to attune yourself to the buried resonance of your people’s lost magic. If successful, you receive a fleeting insight or impression relevant to your current situation. The quality of the outcome is based on your SL. Choose one of these effects: A 1+ SLs: You receive a useful emotional imprint (for example, “This place was a battleground, ” or “Someone is lying to you. ” ) A 4+ SLs: A forgotten word, rune, or phrase surfaces in your mind. It grants +30 to your next Ancient Lore , Arcana , or Insight roll. A 6+ SLs: A half-memory of a Seethie magical technique flickers through you, granting a one-time +3 SL bonus to the outcome of the next successful Bind roll you make. A 8+ SLs: The Seethie thought coalesces briefly into lucidity. You may ask the GM a single specific question related to your current environment or decision and receive a symbolic but useful answer."},{"name":"Hunted By The Queen","category":"Non-Human","sub":false,"requires":"","rank":"once","desc":"Replaced only, mandatory at character creation . You were abducted and enslaved by the minions of the Dark Fae lords. You spent countless years trapped in their dreamy nightmare realm, a mortal plaything of strange elder beings. Finally, you found a way to escape through the Thorns, the supernatural boundary between worlds. Though free, you now carry a fragment of the Glamour: a lingering sliver of the power they used on you. But the Fae Queen never gives up her toys. The Queen’s Hunt is always on your trail, appearing in many forms, at the worst possible times. A Glamour - By spending 3 Resolve and making a successful Willpower roll, you can make yourself look like anyone a single target would consider friendly or desirable. This lasts for a few hours, or until you do something they would consider suspicious, at which point they get an Insight roll to see through the effect. Further suspicious actions grant a cumulative +20 to the Insight roll. Most individuals are not pleased once they realize they’ve been deceived by the Glamour. A Seduction of the Fae: Resolve spent on Perform (only with song or instrument), Seduce or Wit rolls against a single target adds +20 per Resolve instead of +10. Failing such a Fae-enhanced roll immediately ends a Social Encounter, or otherwise ends badly, as the NPC sees through the Glamour. This may have violent consequences. A Cast Out of the Weave: A Replaced may never learn Weave magic, and suffers a -10 on any opposed roll made against it. A Legacy of Servitude: A Replaced suffers a 1-pt Wound from any simple contact with cold iron. Such weapons also do +1 damage against them. A Hunted: You were one of the Fae Queen’s playthings, and she wants her slaves back. The Queen’s Hunt is ever at your heels. If you stay in one place for more than a few days, the GM rolls a d20 Timer Die: if the roll is equal to or less than the number of days you have remained in one place, the Hunt has found you. They come in many forms, but their goal is always the same: to drag you back through the Thorns into the “loving” arms of your Fae master."},{"name":"Thornmark","category":"Non-Human","sub":false,"requires":"","rank":"once","desc":"Replaced only. Once per scene, you may roll Insight to sense whether a Fae creature or agent of the Queen’s Hunt is within 300 feet. On a success with 1–4 SLs, you detect a direction and distance—but not identity. This may give you a chance to flee, prepare an ambush, or otherwise act before they arrive. With 5+ SLs, you also recover a blurred memory of your captivity, which grants +10 to any skill roll made in defiance of the Hunt for the first three rounds of the encounter."}];
/* TBE SOLO LIB — shared helpers, injected into every macro at build time. */

const TBE = {};

TBE.prompt = async function (title, content, okLabel = "Roll") {
  const DV2 = foundry.applications?.api?.DialogV2;
  if (DV2) {
    return DV2.prompt({
      window: { title },
      content,
      ok: { label: okLabel, callback: (ev, btn) => Object.fromEntries(new FormData(btn.form)) },
      rejectClose: false
    });
  }
  return new Promise((resolve) => {
    new Dialog({
      title,
      content,
      buttons: {
        ok: {
          label: okLabel,
          callback: (html) => {
            const el = html[0] ?? html;
            const data = {};
            el.querySelectorAll("[name]").forEach((i) => (data[i.name] = i.value));
            resolve(data);
          }
        }
      },
      default: "ok",
      close: () => resolve(null)
    }).render(true);
  });
};

TBE.num = (v, d = 0) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
};

TBE.d100 = async function () {
  const roll = await new Roll("1d100").evaluate();
  return roll;
};

/* Display "00" for 100, zero-pad 1-9. */
TBE.face = (r) => (r === 100 ? "00" : String(r).padStart(2, "0"));

TBE.isDoubles = (r) => r === 100 || (r < 100 && r % 11 === 0);

/*
 * Core TBE resolution for one d100 roll against a modified skill value.
 * Returns { roll, skill, success, crit, critFail, sl, tens, note }
 */
/*
 * expertise is the skill's Expertise level (0, or 2/3/4 for Ex2/Ex3/Ex4, Ch.4
 * p.54 & Ch.8 p.123): on a successful roll it guarantees at least that many
 * SLs, applied as a floor after the tens-die, critical, and skill-over-100
 * SLs are all totalled -- it never reduces a roll that already did better.
 */
TBE.resolve = function (r, skill, expertise = 0) {
  const s = TBE.num(skill, 0);
  const alwaysFail = r >= 99;
  const doubles = TBE.isDoubles(r);
  let success;
  if (alwaysFail) success = false;
  else if (s <= 0) success = r <= 5;
  else if (r <= 5) success = true;
  else success = r <= s;

  let crit = false;
  let critFail = false;
  if (success) {
    if (s <= 0) crit = r === 5;
    else crit = doubles || r === s;
  } else if (s < 100) {
    critFail = doubles && r > s;
  }

  const tens = Math.floor((r % 100) / 10);
  let sl = 0;
  const notes = [];
  if (success) {
    sl = Math.max(1, tens);
    if (crit) {
      sl += 3;
      notes.push("critical success (+3 SL)");
    }
    if (s > 100) {
      const bonus = Math.max(1, Math.floor(((s - 100) % 100) / 10));
      sl += bonus;
      notes.push("skill over 100 (+" + bonus + " SL)");
    }
    if (r <= 5 && r > s) notes.push("01-05 always succeeds");
    const ex = TBE.num(expertise, 0);
    if (ex >= 2 && sl < ex) {
      sl = ex;
      notes.push("Expertise Ex" + ex + " guarantees " + ex + " SL");
    }
  } else {
    if (alwaysFail) notes.push("99-00 always fails");
    if (critFail) notes.push("critical failure");
  }
  return { roll: r, skill: s, success, crit, critFail, sl, tens, notes };
};

TBE.tag = function (res) {
  if (res.success) return res.crit ? "CRITICAL SUCCESS" : "SUCCESS";
  return res.critFail ? "CRITICAL FAILURE" : "FAILURE";
};

TBE.colour = function (res) {
  if (res.success) return res.crit ? "#1f7a1f" : "#2f6f2f";
  return res.critFail ? "#8b1a1a" : "#6b2b2b";
};

TBE.card = function (title, bodyHtml) {
  return (
    '<div class="tbe-card" style="border:1px solid #7a6a4f;border-radius:6px;padding:6px 8px;background:rgba(120,100,60,0.08)">' +
    '<div style="font-weight:bold;letter-spacing:.5px;border-bottom:1px solid #7a6a4f;margin-bottom:4px">' +
    title +
    "</div>" +
    bodyHtml +
    "</div>"
  );
};

TBE.say = async function (content, rolls = []) {
  return ChatMessage.create({
    speaker: ChatMessage.getSpeaker(),
    content,
    rolls,
    sound: rolls.length ? CONFIG.sounds.dice : null
  });
};

/* Read text off a TableResult across v12 / v13+ schemas. */
TBE.resultText = function (r) {
  if (!r) return "";
  return r.text || r.description || r.name || "";
};

TBE.tableRows = function (name) {
  const spec = (TBE_DATA.tables || []).find((t) => t.name === name);
  return spec ? spec.rows : [];
};

/* Roll a table by name. Falls back to the data baked into this macro if the table is absent. */
TBE.drawTable = async function (name) {
  const t = game.tables.getName(name);
  if (t) {
    const out = await t.roll();
    return { text: TBE.resultText(out.results?.[0]), total: out.roll?.total ?? null };
  }
  const rows = TBE.tableRows(name);
  if (!rows.length) {
    ui.notifications?.warn("TBE: no data for '" + name + "'.");
    return null;
  }
  const roll = await new Roll("1d100").evaluate();
  const hit = rows.find((r) => roll.total >= r[0][0] && roll.total <= r[0][1]);
  return { text: hit ? hit[1] : "", total: roll.total };
};

/*
 * Create one roll table, trying every TableResult schema shape Foundry v11-v14 accepts.
 * Returns the table, or throws.
 */
TBE.createTable = async function (name, rows) {
  const existing = game.tables.getName(name);
  if (existing) return existing;
  const table = await RollTable.create({ name, formula: "1d100", replacement: true, displayRoll: true });
  const short = (s) => (s.length > 48 ? s.slice(0, 48) + "..." : s);
  const variants = [
    (r) => ({ range: r[0], weight: 1, type: "text", name: short(r[1]), description: r[1] }),
    (r) => ({ range: r[0], weight: 1, name: short(r[1]), description: r[1] }),
    (r) => ({ range: r[0], weight: 1, type: 0, text: r[1] }),
    (r) => ({ range: r[0], weight: 1, text: r[1] })
  ];
  for (const v of variants) {
    try {
      const made = await table.createEmbeddedDocuments("TableResult", rows.map(v));
      if (made && made.length) return table;
    } catch (err) {
      console.warn("TBE | result shape rejected for " + name + ":", err);
    }
  }
  console.error("TBE | could not populate table " + name);
  return table;
};

/* Create any TBE table that is missing. GM only. */
TBE.ensureTables = async function () {
  const out = { created: [], failed: [] };
  for (const spec of TBE_DATA.tables || []) {
    if (game.tables.getName(spec.name)) continue;
    if (!game.user.isGM) { out.failed.push(spec.name); continue; }
    try {
      await TBE.createTable(spec.name, spec.rows);
      out.created.push(spec.name);
    } catch (err) {
      console.error("TBE | table failed: " + spec.name, err);
      out.failed.push(spec.name);
    }
  }
  return out;
};

/* Roll a full Random Event: focus + two randomizer words (+ Empires List when called for). */
TBE.event = async function () {
  const focus = await TBE.drawTable("TBE: Random Events");
  const w1 = await TBE.drawTable("TBE: Event Randomizers I");
  const w2 = await TBE.drawTable("TBE: Event Randomizers II");
  const f = (focus?.text || "").toUpperCase();
  let list = null;
  if (f.indexOf("LIST ELEMENT") > -1) list = await TBE.drawTable("TBE: Empires List");
  return {
    focus: focus?.text || "?",
    w1: w1?.text || "?",
    w2: w2?.text || "?",
    list: list ? list.text : null
  };
};

TBE.eventHtml = function (e) {
  return (
    '<div style="margin-top:4px;padding:4px;border:1px dashed #7a6a4f;border-radius:4px">' +
    '<div style="font-size:11px;letter-spacing:.5px;opacity:.8">RANDOM EVENT</div>' +
    "<div>" + e.focus + "</div>" +
    '<div style="font-size:16px;margin-top:2px"><b>' + e.w1 + " &middot; " + e.w2 + "</b></div>" +
    (e.list ? '<div style="font-size:12px;margin-top:2px">List element: <i>' + e.list + "</i></div>" : "") +
    "</div>"
  );
};

/* Skill list off the selected token / assigned actor, system-agnostic. */
TBE.actorSkills = function () {
  const actor = canvas.tokens?.controlled?.[0]?.actor ?? game.user?.character ?? null;
  const out = [];
  if (!actor) return out;
  for (const i of actor.items ?? []) {
    if (i.type !== "skill") continue;
    const v = TBE.num(i.system?.value, 0);
    out.push({ name: i.name, value: v, expertise: TBE.num(i.system?.expertise, 0), savvy: !!i.system?.savvy });
  }
  out.sort((a, b) => a.name.localeCompare(b.name));
  return out;
};

/* A picker whose value, if set, overrides the typed skill number. Encodes
 * Expertise and Savvy alongside the value/name so every roll made from a
 * real skill Item (not a hand-typed number) carries them through to
 * TBE.resolve() without a second sheet lookup. */
TBE.skillOptions = function (fieldName = "pick", label = "From sheet") {
  const s = TBE.actorSkills();
  if (!s.length) return "";
  return (
    '<label style="display:block;margin:2px 0">' + label +
    ': <select name="' + fieldName + '" style="width:100%">' +
    '<option value="">-- use the number below --</option>' +
    s.map((x) => '<option value="' + x.value + '|' + x.name + '|' + x.expertise + '|' + (x.savvy ? 1 : 0) + '">' +
      x.name + " (" + x.value + (x.expertise >= 2 ? " Ex" + x.expertise : "") + (x.savvy ? " S" : "") + ")</option>").join("") +
    "</select></label>"
  );
};

/* Returns {value, name, expertise, savvy} from a picker selection, or null. */
TBE.readPick = function (raw) {
  if (!raw) return null;
  const bits = String(raw).split("|");
  return { value: TBE.num(bits[0], 0), name: bits[1] || "", expertise: TBE.num(bits[2], 0), savvy: bits[3] === "1" };
};

/* ---- actor state helpers ----
 * The native TBE system (systems/the-broken-empires) keeps this as real
 * DataModel fields on the actor: system.wounds, system.supply, system.shock,
 * system.fatigue, system.lethalityPenalty, system.deathThreshold, etc. — not
 * flags.tbe.*. Hit-location keys are the schema's camelCase keys (body, rArm,
 * lArm, rLeg, lLeg, head), not the old display-name keys ("Body", "R Arm", ...).
 * TBE.LOC_LABELS below maps schema key -> display label wherever a chat card
 * needs to show one. */
TBE.clone = (o) => (foundry.utils?.duplicate ? foundry.utils.duplicate(o) : JSON.parse(JSON.stringify(o)));

TBE.LOCATIONS = ["body", "rArm", "lArm", "rLeg", "lLeg", "head"];

/* Ch.18 Size ladder, smallest to largest. Medium (index 5) is the human
 * baseline. Mirrors the system's own chargen-data.mjs. */
TBE.SIZES = ["Minute", "Diminutive", "Tiny", "Little", "Small", "Medium",
  "Large", "Huge", "Massive", "Gargantuan", "Colossal"];

/*
 * Combat consequences of the Size gap between two combatants (Ch.18), from the
 * attacker's point of view. gap > 0 means the DEFENDER is larger. Returns plain
 * data so a chat card can show its reasoning instead of silently nudging
 * numbers. Note this is the size DIFFERENCE table, which always applies; the
 * separate per-step stat table (+1 Toughness, +2 damage...) is only for a
 * creature whose size has been CHANGED from its starting size, and bestiary
 * stat blocks already bake their own size in.
 */
TBE.sizeEffects = function (attackerSize, defenderSize) {
  const ai = TBE.SIZES.indexOf(attackerSize), di = TBE.SIZES.indexOf(defenderSize);
  if (ai < 0 || di < 0) return null;
  const gap = di - ai, abs = Math.abs(gap);
  return {
    gap, abs,
    attackerSize, defenderSize,
    /* "All Combat skills used against a creature 3+ Sizes larger are at +20." */
    toHit: gap >= 3 ? 20 : 0,
    /* "Melee attacks from a creature 3+ Sizes larger cannot be parried, only
       Dodged." On this attack that bites when the ATTACKER is the larger one. */
    defenderMustDodge: gap <= -3,
    /* "Drive Back, Trip and Disarm cannot be used against a creature 3+ Sizes larger." */
    maneuversBlocked: gap >= 3 ? ["db", "trip", "dis"] : [],
    /* "+1 Reach per 2 Sizes larger than the opponent." */
    attackerReach: Math.trunc(Math.max(0, -gap) / 2),
    defenderReach: Math.trunc(Math.max(0, gap) / 2),
    /* "Grappling is only possible up to 2 Sizes larger or smaller." */
    grappleLegal: abs <= 2,
    /* "+20 Might per Size category of difference when Grappling" (to the larger). */
    grappleMight: abs * 20
  };
};

/* Human-readable lines for whatever the size gap actually changed. */
TBE.sizeNotes = function (fx, attackerName, defenderName) {
  if (!fx || !fx.gap) return [];
  const out = [];
  const bigger = fx.gap > 0 ? defenderName : attackerName;
  out.push("Size: " + fx.attackerSize + " vs " + fx.defenderSize + " (" +
    bigger + " larger by " + fx.abs + ")");
  if (fx.toHit) out.push("+" + fx.toHit + " to hit: target is 3+ Sizes larger");
  if (fx.defenderMustDodge) out.push("Monstrous attack: " + defenderName + " cannot parry, only Dodge");
  if (fx.maneuversBlocked.length) out.push("Drive Back, Trip and Disarm are unavailable against a foe 3+ Sizes larger");
  if (fx.attackerReach) out.push(attackerName + " has +" + fx.attackerReach + " Reach");
  if (fx.defenderReach) out.push(defenderName + " has +" + fx.defenderReach + " Reach");
  if (!fx.grappleLegal) out.push("Grappling is impossible at more than 2 Sizes apart");
  else if (fx.grappleMight) out.push("In a Grapple the larger gains +" + fx.grappleMight + " Might");
  return out;
};
TBE.LOC_LABELS = { body: "Body", rArm: "R Arm", lArm: "L Arm", rLeg: "R Leg", lLeg: "L Leg", head: "Head" };

TBE.emptyWoundLoc = () => ({ wp: 0, imp: 0, inf: false, septic: false, rb: null });
TBE.wounds = function (actor) {
  const w = TBE.clone(actor?.system?.wounds ?? {});
  for (const loc of TBE.LOCATIONS) if (!w[loc]) w[loc] = TBE.emptyWoundLoc();
  return w;
};
TBE.setWounds = async (actor, w) => actor.update({ "system.wounds": w });

/* Whole-character Shock (Ch.11) is its own boolean field now, not a synthetic
 * "__shock" key folded into the wounds object. */
TBE.shock = (actor) => !!actor?.system?.shock;
TBE.setShock = async (actor, val) => actor.update({ "system.shock": !!val });

/* Encumbrance (Ch.9 p.129-130): Weapons at Hand (max 6 ENC, shared by weapon
 * and shield items carried "hand"), and general Inventory ENC (max 6 + a
 * manual invBonus for things like the Strong Back Talent, no auto-detect
 * hook for Talent effects in this system) -- coins (1 ENC/500sp), stored
 * weapons/shields, and un-equipped armor pieces (1 ENC each, since a worn
 * piece is free per location instead) all count against Inventory.
 * Overflow above Max Inventory ENC penalises "physical activity" rolls
 * (Athletics, Combat skills, etc, p.130) -- callers apply TBE.encStatus().penalty
 * themselves (as a prefilled, editable modifier) rather than this silently
 * altering a roll no one can see. */
TBE.encStatus = function (actor) {
  const items = actor?.items ?? [];
  const hand = items.filter((i) => (i.type === "weapon" || i.type === "shield") && (i.system?.carried ?? "hand") !== "stored")
    .reduce((s, i) => s + TBE.num(i.system?.enc, 0), 0);
  const storedGear = items.filter((i) => (i.type === "weapon" || i.type === "shield") && i.system?.carried === "stored")
    .reduce((s, i) => s + TBE.num(i.system?.enc, 0), 0);
  const unequippedArmor = items.filter((i) => i.type === "armor" && i.system?.equipped === false).length;
  const coinEnc = Math.floor(TBE.num(actor?.system?.silver, 0) / 500);
  const inv = storedGear + unequippedArmor + coinEnc;
  const invMax = 6 + TBE.num(actor?.system?.enc?.invBonus, 0);
  const over = Math.max(0, inv - invMax);
  const penalty = over <= 0 ? 0 : over <= 3 ? -10 : over <= 6 ? -20 : over <= 9 ? -30 : -30;
  return { hand, handMax: 6, inv, invMax, over, penalty, overCap: over > 9 };
};

/* Short reminder line for a roll dialog: only prints anything when there's
 * an actual overflow penalty in effect, so a clean sheet stays silent. */
TBE.encNote = function (actor) {
  if (!actor) return "";
  const e = TBE.encStatus(actor);
  if (!e.penalty) return "";
  return '<div style="font-size:11px;color:#b04040">' + (actor.name || "Actor") + ": " + e.inv + "/" + e.invMax +
    " Inventory ENC, " + e.over + " over &rarr; <b>" + e.penalty + "</b> to physical-activity rolls (Athletics, Combat skills)" +
    (e.overCap ? " &mdash; over the 9-point cap, drop something, this is not a legal load" : "") + ".</div>";
};

TBE.SUPPLY_STEPS = [6, 8, 10, 12];
TBE.supply = (actor) => Object.assign({ gear: 8, ammo: 8, medical: 8, rations: 8 }, TBE.clone(actor?.system?.supply ?? {}));
TBE.setSupply = async (actor, s) => actor.update({ "system.supply": s });

/* Roll a supply die: 1-2 steps it down; a d6 that steps down is depleted (0). */
TBE.rollSupply = async function (actor, key, force) {
  const s = TBE.supply(actor);
  const die = TBE.num(s[key], 8);
  if (die <= 0) return { die: 0, roll: null, stepped: false, depleted: true, text: key + " is already exhausted" };
  const r = await new Roll("1d" + die).evaluate();
  const stepped = force || r.total <= 2;
  let next = die;
  if (stepped) next = die === 6 ? 0 : TBE.SUPPLY_STEPS[TBE.SUPPLY_STEPS.indexOf(die) - 1] ?? 6;
  if (stepped) { s[key] = next; await TBE.setSupply(actor, s); }
  return {
    die, roll: r, next, stepped, depleted: next === 0,
    text: key + " d" + die + ": rolled " + r.total +
      (stepped ? (next === 0 ? " &mdash; <b>exhausted</b>" : " &mdash; steps down to d" + next) : ", holds")
  };
};

/* Total lethal WP across locations. */
TBE.totalWp = (w) => Object.values(w || {}).reduce((a, b) => a + TBE.num(b.wp, 0), 0);

TBE.woundTable = function (w) {
  const keys = TBE.LOCATIONS.filter((k) => w[k] && (TBE.num(w[k].wp, 0) > 0 || TBE.num(w[k].imp, 0) > 0));
  if (!keys.length) return "<div><i>No wounds recorded.</i></div>";
  return '<table style="width:100%;border-collapse:collapse;font-size:12px">' +
    "<tr><th align='left'>Location</th><th align='left'>WP</th><th align='left'>State</th></tr>" +
    keys.map((k) => {
      const x = w[k];
      const tags = [];
      if (TBE.num(x.imp, 0) >= 2) tags.push("Shock");
      else if (TBE.num(x.imp, 0) === 1) tags.push("Impaired");
      if (x.septic) tags.push("<b>SEPTIC</b>");
      else if (x.inf) tags.push("<b>Infected</b>");
      if (x.rb !== undefined && x.rb !== null) tags.push("RB " + (x.rb >= 0 ? "+" : "") + x.rb);
      return "<tr><td>" + (TBE.LOC_LABELS[k] || k) + "</td><td>" + TBE.num(x.wp, 0) + "</td><td>" + (tags.join(", ") || "&mdash;") + "</td></tr>";
    }).join("") + "</table>";
};

/* The actor a solo player is driving right now. */
TBE.me = () => canvas.tokens?.controlled?.[0]?.actor ?? game.user?.character ?? null;

/* Read a skill value off a real skill Item by name, tolerant of a trailing
 * "(Sub)" qualifier some maneuver/table text still writes (e.g. "Adventuring
 * (Endurance)" meaning the "Endurance" skill). */
TBE.skillNamed = function (actor, wanted) {
  const w = String(wanted).toLowerCase().trim();
  const inner = w.indexOf("(") > -1 ? w.slice(w.indexOf("(") + 1).replace(")", "").trim() : null;
  for (const i of actor?.items ?? []) {
    if (i.type !== "skill") continue;
    const n = i.name.toLowerCase();
    if (n === w || (inner && n === inner)) {
      return { name: i.name, value: TBE.num(i.system?.value, 0), expertise: TBE.num(i.system?.expertise, 0), savvy: !!i.system?.savvy };
    }
  }
  return null;
};

/* Find a weapon Item by name (or the first weapon whose linked system.skillName
 * matches), tolerant the same way. Used by tbe-attack.js to resolve the
 * attacking weapon's maneuver-cost fields (cl/cs/dis/t) and damage. */
TBE.weaponNamed = function (actor, wanted) {
  if (!wanted) return null;
  const w = String(wanted).toLowerCase().trim();
  for (const i of actor?.items ?? []) {
    if (i.type !== "weapon") continue;
    if (i.name.toLowerCase() === w) return i;
  }
  return null;
};

/* ---------------------------------------------------------------------------
 * Status effects: one registry, shared by every macro, so a wound, a maneuver
 * rider, or a peril always shows the same token icon rather than each macro
 * inventing its own. Grouped to match the book's own chapters (Ch.10 Combat,
 * Ch.11 Wounds/Healing/Perils, Ch.14 Weave Magic), so "TBE: Status Effects"
 * and the reference journal can render the same list.
 * ------------------------------------------------------------------------- */
TBE.STATUSES = [
  ["Wounds & Impairment", "tbe-imp-body", "Impaired: Body", "icons/svg/blood.svg"],
  ["Wounds & Impairment", "tbe-imp-rarm", "Impaired: R Arm", "icons/svg/blood.svg"],
  ["Wounds & Impairment", "tbe-imp-larm", "Impaired: L Arm", "icons/svg/blood.svg"],
  ["Wounds & Impairment", "tbe-imp-rleg", "Impaired: R Leg", "icons/svg/blood.svg"],
  ["Wounds & Impairment", "tbe-imp-lleg", "Impaired: L Leg", "icons/svg/blood.svg"],
  ["Wounds & Impairment", "tbe-imp-head", "Impaired: Head", "icons/svg/blood.svg"],
  ["Wounds & Impairment", "tbe-stunned", "Stunned", "icons/svg/daze.svg"],
  ["Wounds & Impairment", "tbe-prone", "Prone", "icons/svg/falling.svg"],
  ["Wounds & Impairment", "tbe-unconscious", "Unconscious", "icons/svg/paralysis.svg"],
  ["Wounds & Impairment", "tbe-arm-useless", "Arm Useless", "icons/svg/downgrade.svg"],
  ["Wounds & Impairment", "tbe-leg-hobbled", "Leg Hobbled", "icons/svg/downgrade.svg"],
  ["Wounds & Impairment", "tbe-shock", "Shock", "icons/svg/unconscious.svg"],
  ["Wounds & Impairment", "tbe-dying", "Dying", "icons/svg/skull.svg"],
  ["Wounds & Impairment", "tbe-infected", "Infected", "icons/svg/biohazard.svg"],
  ["Wounds & Impairment", "tbe-septic", "Septic", "icons/svg/poison.svg"],
  ["Maneuver Riders", "tbe-unbalanced", "Unbalanced", "icons/svg/downgrade.svg"],
  ["Maneuver Riders", "tbe-locked", "Locked", "icons/svg/net.svg"],
  ["Maneuver Riders", "tbe-disarmed", "Disarmed", "icons/svg/downgrade.svg"],
  ["Maneuver Riders", "tbe-disadvantaged", "Disadvantaged", "icons/svg/downgrade.svg"],
  ["Magic", "tbe-restrained", "Restrained", "icons/svg/net.svg"],
  ["Fatigue & Travel", "tbe-fatigued", "Fatigued", "icons/svg/sleep.svg"],
  ["Fatigue & Travel", "tbe-weary", "Weary", "icons/svg/sleep.svg"],
  ["Fatigue & Travel", "tbe-deprived", "Deprived", "icons/svg/hazard.svg"],
  ["Fatigue & Travel", "tbe-sleepless", "Sleepless", "icons/svg/sleep.svg"],
  ["Other Perils", "tbe-blinded", "Blinded", "icons/svg/blind.svg"],
  ["Other Perils", "tbe-deafened", "Deafened", "icons/svg/deaf.svg"],
  ["Other Perils", "tbe-frostbite", "Frostbite", "icons/svg/frozen.svg"],
  ["Other Perils", "tbe-burning", "Burning", "icons/svg/fire.svg"],
  ["Other Perils", "tbe-poisoned", "Poisoned", "icons/svg/poison.svg"],
  ["Other Perils", "tbe-feared", "Feared", "icons/svg/terror.svg"]
].map(([group, id, name, icon]) => ({ group, id, name, icon }));

/* Register the whole palette into CONFIG.statusEffects, idempotently. Every macro
 * loads _lib.js, so this runs whenever any TBE tool is used — no separate install
 * step needed, and the right-click token HUD always has the full palette ready. */
TBE.ensureStatuses = function () {
  try {
    if (!Array.isArray(CONFIG.statusEffects)) return;
    for (const s of TBE.STATUSES) {
      if (!CONFIG.statusEffects.find((e) => e.id === s.id)) {
        CONFIG.statusEffects.push({ id: s.id, name: s.name, label: s.name, img: s.icon, icon: s.icon });
      }
    }
  } catch (eEnsure) { /* older builds may not expose CONFIG.statusEffects as a plain array */ }
};
TBE.ensureStatuses();

TBE.statusDef = (id) => TBE.STATUSES.find((s) => s.id === id) ?? null;

TBE.hasStatus = function (actor, id) {
  try { if (actor?.statuses?.has && actor.statuses.has(id)) return true; } catch (eHas) {}
  try {
    const effects = actor?.effects?.contents ?? actor?.effects ?? [];
    return effects.some((e) => (e.statuses?.has?.(id)) || e.flags?.core?.statusId === id);
  } catch (eHas2) { return false; }
};

/* Apply a status the same way everywhere: the core toggle API first (this is what
 * actually paints a token icon), a raw ActiveEffect with "statuses" populated as a
 * fallback for older builds where toggleStatusEffect isn't available. Returns
 * true/false so a chat card can say honestly whether it landed. */
TBE.applyStatus = async function (actor, id, opts) {
  if (!actor || TBE.hasStatus(actor, id)) return !!actor;
  const def = TBE.statusDef(id) ?? { id, name: id, icon: "icons/svg/aura.svg" };
  TBE.ensureStatuses();
  try {
    await actor.toggleStatusEffect(id, Object.assign({ active: true, overlay: false }, opts));
    return true;
  } catch (eToggle) {
    try {
      await actor.createEmbeddedDocuments("ActiveEffect", [{
        name: def.name, img: def.icon, duration: (opts && opts.duration) || {}, statuses: [id]
      }]);
      return true;
    } catch (eCreate) { return false; }
  }
};

TBE.clearStatus = async function (actor, id) {
  if (!actor || !TBE.hasStatus(actor, id)) return !!actor;
  try {
    await actor.toggleStatusEffect(id, { active: false });
    return true;
  } catch (eToggle) {
    try {
      const effects = actor.effects?.contents ?? actor.effects ?? [];
      const dead = effects.filter((e) => e.statuses?.has?.(id) || e.flags?.core?.statusId === id).map((e) => e.id);
      if (dead.length) await actor.deleteEmbeddedDocuments("ActiveEffect", dead);
      return true;
    } catch (eDelete) { return false; }
  }
};

/* Reconcile the token icons for the states this pack already tracks as plain data
 * (wounds/impairment/infection/sepsis/shock/dying) with what's actually recorded in
 * system.wounds and the Death Threshold. Safe to call often — every Attack, every Heal action, and
 * every time the Status card is opened — so hand-edits or a skipped step never leave
 * a token showing something stale. Riders (Unbalance, Restrained, ...) and manual
 * perils (Fatigued, Blinded, ...) are applied at the point they happen instead, since
 * nothing else records their state to reconcile against. */
TBE.syncStatuses = async function (actor) {
  if (!actor) return;
  const w = TBE.wounds(actor);
  const locMap = { body: "tbe-imp-body", rArm: "tbe-imp-rarm", lArm: "tbe-imp-larm",
    rLeg: "tbe-imp-rleg", lLeg: "tbe-imp-lleg", head: "tbe-imp-head" };
  for (const [loc, id] of Object.entries(locMap)) {
    const should = TBE.num(w[loc]?.imp, 0) > 0;
    if (should !== TBE.hasStatus(actor, id)) await (should ? TBE.applyStatus(actor, id, {}) : TBE.clearStatus(actor, id));
  }
  /* Shock is a real system.shock boolean field (see tbe-attack.js), not re-derived
   * from wound counts here, since a Head impairment on an even Wound Die also forces
   * Shock without any location ever reaching a second impairment. */
  const shockNow = TBE.shock(actor);
  if (shockNow !== TBE.hasStatus(actor, "tbe-shock")) await (shockNow ? TBE.applyStatus(actor, "tbe-shock", {}) : TBE.clearStatus(actor, "tbe-shock"));
  const infected = Object.values(w).some((x) => x.inf);
  if (infected !== TBE.hasStatus(actor, "tbe-infected")) await (infected ? TBE.applyStatus(actor, "tbe-infected", {}) : TBE.clearStatus(actor, "tbe-infected"));
  const septic = Object.values(w).some((x) => x.septic);
  if (septic !== TBE.hasStatus(actor, "tbe-septic")) await (septic ? TBE.applyStatus(actor, "tbe-septic", {}) : TBE.clearStatus(actor, "tbe-septic"));
  /* Death Threshold, Lethality Level and total WP are real DataModel getters
   * on the live actor.system now — no need to re-derive them here. */
  const dt = TBE.num(actor.system?.deathThreshold?.max, 0);
  const dying = dt > 0 && !!actor.system?.dying;
  if (dying !== TBE.hasStatus(actor, "tbe-dying")) await (dying ? TBE.applyStatus(actor, "tbe-dying", {}) : TBE.clearStatus(actor, "tbe-dying"));
};

/* ---------------------------------------------------------------------------
 * Extended Roll / Social Encounter trackers (Ch.2 p.22, Ch.13 p.249-264): a
 * task or scene that plays out over more than one standard roll, accumulating
 * SLs toward a threshold. Tracked state belongs to the undertaking, not to
 * any one actor, so it lives in a world setting (registered by the system's
 * init hook, namespace "the-broken-empires") rather than on a character sheet.
 * Multiple trackers can be active at once (a crafting project running
 * alongside a negotiation), each keyed by its own id.
 * ------------------------------------------------------------------------- */
TBE.TRACKER_SETTING = "encounters";

TBE.trackers = function () {
  try { return TBE.clone(game.settings.get("the-broken-empires", TBE.TRACKER_SETTING) || {}); }
  catch (eGet) { return {}; }
};

TBE.saveTracker = async function (t) {
  const all = TBE.trackers();
  all[t.id] = t;
  await game.settings.set("the-broken-empires", TBE.TRACKER_SETTING, all);
  return t;
};

TBE.deleteTracker = async function (id) {
  const all = TBE.trackers();
  delete all[id];
  await game.settings.set("the-broken-empires", TBE.TRACKER_SETTING, all);
};

TBE.newTrackerId = () => "t" + Date.now().toString(36) + Math.floor(Math.random() * 46656).toString(36);

/* Every roll in these systems is a plain standard roll (p.19-22): TBE.resolve
 * already carries the tens-die SL count, the +3 critical-success bonus, and
 * the over-100-skill bonus, so extended/social rolls reuse it rather than
 * reimplementing SL math a second time. */
TBE.rollAttempt = async function (skillValue, expertise = 0) {
  const roll = await TBE.d100();
  return { roll, r: TBE.resolve(roll.total, skillValue, expertise) };
};

/* Halve-round-up, the shared critical-failure penalty across Extended Rolls
 * and both Social Encounter variants. Never drops below zero. */
TBE.halveUp = (n) => Math.max(0, Math.ceil(n / 2));

/* TBE: Character Wizard — a real persistent, step-back-able chargen flow
 * that now follows the book's actual 12-step order (Ch.7 p.78), not just the
 * subset the old `TBE: Build Character` macro covered. One window, forward
 * and back navigation, nothing written to the actor until Create Character
 * on the final page.
 *
 * Scope, deliberately, per direct user steer ("show tables in name only, not
 * full detail, I have the book"):
 *   - Fully applied to the actor (compact, well-defined mechanics, same
 *     standard as Race/Career already got): Starting Skills, Race, Ability
 *     Scores, Attributes, Cultural Background (incl. Human Culture Language),
 *     Previous Career, Career Skill Points, Rounding Out, Talents.
 *   - Table shown (name + d100/d10/d4 range, roll button) but NOT
 *     mechanically auto-applied, because each result's exact bonus needs a
 *     player choice among 2-3 skills that the book states in prose, not a
 *     clean data table: Life Events (Origin/Youth/Recent), Shared History,
 *     Relationship NPCs. The rolled/picked name is recorded to the Notes tab
 *     so the player can look up the exact line in their own copy and apply
 *     it via the Skills tab.
 *   - Free text, no table: Character Goals.
 *   - Info only: Equip Your Character (dagger auto-added from the
 *     compendium, armor-piece count and starting coin rolled and reported,
 *     but actual shopping stays on the Gear tab -- a full purchase UI is a
 *     separate project), Status (Optional).
 *
 * Built as classic `Application` (v1), not ApplicationV2 -- this pack still
 * targets Foundry v11, where ApplicationV2 doesn't exist.
 *
 * The draft lives only in this window's memory, not on the actor or in a
 * flag. Cross-session persistence remains a tracked BACKLOG.md gap.
 */

const CHARGEN_SKILL_CAP = 70;
const SKILLS = {
  Combat: ["Dodge", "Melee: Light", "Melee: Medium", "Melee: Heavy", "Might", "Missile", "Thrown"],
  Adventuring: ["Athletics", "Endurance", "Locks & Traps", "Perception", "Ride", "Sail/Boat",
    "Sleight of Hand", "Stealth", "Survival", "Track", "Willpower"],
  Social: ["Deceive", "Insight", "Inspire", "Intimidate", "Perform", "Persuade", "Protocol", "Seduce", "Wit"],
  Lore: ["Ancient Lore", "Arcana", "Commerce", "Common Lore", "Craft: Artistic", "Craft: Practical",
    "Divinity", "Heal", "Naturewise", "Streetwise"]
};
const SKILL_ALL = Object.values(SKILLS).flat();
const RELATIONSHIP_TYPES = [{ d4: 1, name: "Friend" }, { d4: 2, name: "Patron" }, { d4: 3, name: "Rival" }, { d4: 4, name: "Adversary" }];

const actor = canvas.tokens?.controlled?.[0]?.actor ?? game.user?.character ?? null;
if (!actor) {
  ui.notifications?.warn("TBE: select a token, or set an assigned character, then run this again.");
} else {

  const RACES = TBE_CHARGEN.races || [];
  const CAREERS = TBE_CHARGEN.careers || [];
  const ABILITY_SCORES = TBE_CHARGEN.abilityScores || [];
  const CULTURES = TBE_CHARGEN.culturalBackgrounds || [];
  const HUMAN_CULTURES = TBE_CHARGEN.humanCultures || [];
  const LIFE_EVENTS = TBE_CHARGEN.lifeEvents || { origin: [], youth: [], recent: [] };
  const ROUNDING_OUT_AGES = TBE_CHARGEN.roundingOutAges || [];
  const PERSONALITY_TRAITS = TBE_CHARGEN.personalityTraits || [];
  const bareName = (n) => n.replace(/\s*\([^)]*\)\s*$/, "").toLowerCase().trim();

  /* ---- random determination helpers (every table below is named in the
     book as an explicit "or roll" option alongside picking by hand). ------ */
  // `max` is the die's face count (100 for d100, 10 for d10): the book writes
  // the top of a range as "0" (d10, e.g. "9-0" = 9 or 10) or "00" (d100, e.g.
  // "99-00" = 99 or 100) rather than the literal number, so a trailing 0 has
  // to be reinterpreted as `max`, not taken at face value -- otherwise the
  // very last row of every such table (the one landing on the die's max
  // face) silently never matches any roll.
  function parseD100Range(s, max) {
    max = max || 100;
    if (s === "00" || s === "0") return [max, max];
    const m = String(s).match(/(\d+)\s*-\s*(\d+)/);
    if (m) {
      const lo = parseInt(m[1], 10);
      let hi = parseInt(m[2], 10);
      if (hi === 0) hi = max;
      return [lo, hi];
    }
    const n = parseInt(s, 10);
    return [n, n];
  }
  function forRoll(table, roll, rangeKey, max) {
    for (const r of table) {
      const [lo, hi] = parseD100Range(r[rangeKey] ?? r.range ?? r.d100, max);
      if (roll >= lo && roll <= hi) return r;
    }
    return null;
  }
  function raceForRoll(roll) { return forRoll(RACES, roll, "d100", 100); }
  function careerForRoll(roll) { return CAREERS.find((c) => Number(c.d10) === roll) || null; }
  function cultureBgForRoll(roll) { return forRoll(CULTURES, roll, "range", 10); }
  function humanCultureForRoll(roll) { return forRoll(HUMAN_CULTURES, roll, "range", 100); }
  function lifeEventForRoll(table, roll) { return forRoll(table, roll, "range", 100); }
  function rollTableHtml(rows, colHead) {
    return '<table style="width:100%;font-size:11px;margin-top:8px;border-collapse:collapse;opacity:.9">' +
      "<thead><tr><th style=\"text-align:left;border-bottom:1px solid #7a6a4f\">" + colHead +
      "</th><th style=\"text-align:left;border-bottom:1px solid #7a6a4f\">Result</th></tr></thead><tbody>" +
      rows.map((r) => "<tr" + (r.hit ? ' style="font-weight:bold;color:#e0ac5c"' : "") +
        "><td>" + r.range + "</td><td>" + r.name + "</td></tr>").join("") + "</tbody></table>";
  }
  function resolveOptions(token) {
    if (Array.isArray(token)) return token;
    if (typeof token === "string" && token.indexOf("CAT:") === 0) {
      return token.slice(4).split("+").reduce((out, c) => out.concat(SKILLS[c] || []), []);
    }
    return [];
  }
  function raiseExpertise(cur) { return cur === 0 ? 2 : Math.min(4, cur + 1); }

  /* ---- pure helpers, shared between step previews and the final commit so
     the two can never silently disagree with each other. ------------------ */

  function poolCats(career) {
    return Object.entries(career.pools || {}).filter(([cat, pool]) => pool && cat !== "Magic" && (SKILLS[cat] || []).length);
  }
  function evenSplit(career) {
    const alloc = {};
    for (const [cat, pool] of poolCats(career)) {
      const names = SKILLS[cat];
      const each = Math.floor(pool / names.length);
      let rest = pool - each * names.length;
      names.forEach((n, idx) => {
        alloc[cat + "_" + idx] = each + (rest > 0 ? 1 : 0);
        if (rest > 0) rest--;
      });
    }
    return alloc;
  }

  /* Base values (step 1) + the 4 category "boost one skill to 30" choices,
     career pool spend, race mods, Ability Score bonuses, and Cultural
     Background bonuses -- all layered onto one values map so nothing has to
     be reconciled twice between preview and commit. */
  function computeSkillValues(draft) {
    const base = TBE.num(draft.base, 20);
    const values = {};
    for (const group of Object.keys(SKILLS)) {
      for (const name of SKILLS[group]) values[name] = { group, value: base, fighting: group === "Combat", expertise: 0 };
    }
    const notesOut = [];

    // Step 1: one skill per category (except Magic) to 30 -- i.e. +10 over the base 20.
    for (const [cat, skill] of Object.entries(draft.boost || {})) {
      if (skill && values[skill]) values[skill].value = Math.min(CHARGEN_SKILL_CAP, values[skill].value + 10);
    }

    // Step 7/skill points: career pools, spent by the player.
    const career = CAREERS.find((c) => c.name === draft.careerName) || CAREERS[0];
    const spent = [];
    for (const [cat, pool] of Object.entries(career.pools || {})) {
      if (!pool) continue;
      if (cat === "Magic") { notesOut.push("Magic pool of " + pool + " points: assign by hand to your Bind skills (no Bind may exceed 70)."); continue; }
      const names = SKILLS[cat] || [];
      if (!names.length) continue;
      let allocated = 0;
      names.forEach((n, idx) => {
        const add = Math.max(0, TBE.num((draft.alloc || {})[cat + "_" + idx], 0));
        allocated += add;
        values[n].value = Math.min(CHARGEN_SKILL_CAP, values[n].value + add);
      });
      spent.push(cat + " " + allocated + "/" + pool);
      if (allocated !== pool) {
        notesOut.push(cat + ": you allocated " + allocated + " of " + pool + " points" +
          (allocated < pool ? " (" + (pool - allocated) + " unspent, add them later via TBE: Advancement or the Skills tab)" : " (over the pool by " + (allocated - pool) + " -- trim it on the Skills tab)") + ".");
      }
    }

    // Step 2: racial modifiers.
    const race = RACES.find((r) => r.name === draft.raceName) || RACES[0];
    const raceApplied = [];
    for (const m of race.skillMods || []) {
      if (!values[m.skill]) { notesOut.push("Racial modifier " + (m.mod > 0 ? "+" : "") + m.mod + " to " + m.skill + ": no such skill on the list, apply by hand."); continue; }
      values[m.skill].value = Math.max(0, values[m.skill].value + m.mod);
      raceApplied.push(m.skill + " " + (m.mod > 0 ? "+" : "") + m.mod);
    }

    // Step 3: Ability Scores -- +5 to each listed skill, +1 Expertise to one of them.
    const abilityApplied = [];
    (draft.abilityPicks || []).forEach((scoreName, i) => {
      if (!scoreName) return;
      const score = ABILITY_SCORES.find((a) => a.name === scoreName);
      if (!score) return;
      for (const sk of score.skills) if (values[sk]) values[sk].value = Math.min(CHARGEN_SKILL_CAP, values[sk].value + 5);
      const exSkill = (draft.abilityExpertise || [])[i];
      if (exSkill && values[exSkill]) values[exSkill].expertise = raiseExpertise(values[exSkill].expertise);
      abilityApplied.push(scoreName + " (+5 to " + score.skills.join(", ") + (exSkill ? ", Ex to " + exSkill : "") + ")");
    });

    // Step 5: Cultural Background picks.
    const cultureApplied = [];
    const culture = CULTURES.find((c) => c.name === draft.cultureBgName);
    if (culture) {
      culture.picks.forEach((pick, pi) => {
        const chosen = (draft.cultureBgPicks || {})[pi] || [];
        chosen.forEach((sk) => {
          if (!sk || !values[sk]) return;
          if (pick.expertise) { values[sk].expertise = raiseExpertise(values[sk].expertise); cultureApplied.push(sk + " Ex"); }
          else { values[sk].value = Math.min(CHARGEN_SKILL_CAP, values[sk].value + pick.amount); cultureApplied.push(sk + " +" + pick.amount); }
        });
      });
    }

    // Step 8: Rounding Out -- age bonuses (Endurance/DT handled by caller for DT;
    // Endurance is a normal skill so it's handled here), Expertise, bonus pools.
    const age = ROUNDING_OUT_AGES.find((a) => a.key === draft.roAge);
    const roApplied = [];
    if (age) {
      if (age.endurance && values.Endurance) {
        values.Endurance.value = Math.max(0, Math.min(CHARGEN_SKILL_CAP, values.Endurance.value + age.endurance));
        roApplied.push("Endurance " + (age.endurance > 0 ? "+" : "") + age.endurance + " (" + age.key + ")");
      }
      if (age.expertise && draft.roOldExpertiseSkill && values[draft.roOldExpertiseSkill]) {
        values[draft.roOldExpertiseSkill].expertise = raiseExpertise(values[draft.roOldExpertiseSkill].expertise);
        roApplied.push(draft.roOldExpertiseSkill + " Ex (Old)");
      }
      for (const [sk, pts] of Object.entries(draft.roAlloc || {})) {
        const add = Math.max(0, TBE.num(pts, 0));
        if (add && values[sk]) { values[sk].value = Math.min(CHARGEN_SKILL_CAP, values[sk].value + add); roApplied.push(sk + " +" + add + " (bonus)"); }
      }
      for (const [sk, pts] of Object.entries(draft.roLoreAlloc || {})) {
        const add = Math.max(0, TBE.num(pts, 0));
        if (add && values[sk] && SKILLS.Lore.includes(sk)) { values[sk].value = Math.min(CHARGEN_SKILL_CAP, values[sk].value + add); roApplied.push(sk + " +" + add + " (Old Lore bonus)"); }
      }
    }
    for (const sk of (draft.roSavvy || [])) if (sk && values[sk]) values[sk].savvy = true;

    return { values, spent, raceApplied, abilityApplied, cultureApplied, roApplied, notesOut, race, career, age };
  }

  function computeTalents(race, career) {
    const wanted = [];
    for (const t of race.exclusiveTalents || []) wanted.push({ name: t, why: race.name + " exclusive" });
    const careerTalentText = career.talents || "";
    const careerLower = careerTalentText.toLowerCase();
    for (const t of TBE_TALENTS) {
      const bare = bareName(t.name);
      if (bare.length >= 4 && careerLower.indexOf(bare) > -1) wanted.push({ name: t.name, why: career.name + " career" });
    }
    return { wanted, careerTalentText };
  }
  function resolveTalentPayload(wanted, race, career) {
    const talentPayload = [];
    const notesOut = [];
    const seen = new Set();
    for (const w of wanted) {
      const key = w.name.toLowerCase();
      if (seen.has(key)) continue;
      seen.add(key);
      const rec = TBE_TALENTS.find((t) => t.name.toLowerCase() === key);
      if (!rec) { notesOut.push("Talent '" + w.name + "' (" + w.why + ") is not in the catalogue, add it by hand."); continue; }
      talentPayload.push({
        name: rec.name, type: "talent", img: "icons/svg/upgrade.svg",
        system: { category: rec.category, requirements: rec.requires || "", ranks: 1, maxRanks: rec.rank, specialization: "", sub: !!rec.sub, description: "<p>" + rec.desc + "</p>" }
      });
    }
    const romanRank = (career.talents || "").match(/Armor Training (I{1,3}V?|IV)/i);
    if (romanRank) {
      const r = { I: 1, II: 2, III: 3, IV: 4 }[romanRank[1].toUpperCase()] || 1;
      const at = talentPayload.find((t) => /^armor training/i.test(t.name));
      if (at) { at.system.ranks = r; at.system.specialization = "up to " + ["Reinforced Leather", "Mail", "Scale", "Plate"][r - 1]; }
    }
    for (const lim of race.talentLimits || []) {
      const hit = talentPayload.find((t) => t.name.toLowerCase().indexOf(lim.talent.toLowerCase()) > -1);
      if (hit && hit.system.ranks > lim.maxRanks) {
        notesOut.push(race.name + " caps " + lim.talent + " at " + lim.maxRanks + " rank (" + lim.note + "), down from the career's " + hit.system.ranks + ".");
        hit.system.ranks = lim.maxRanks;
        hit.system.specialization = lim.note;
      }
    }
    return { talentPayload, notesOut };
  }

  class TBECharacterWizard extends Application {
    constructor(targetActor, opts = {}) {
      super(opts);
      this.actor = targetActor;
      this.step = 0;
      this.STEP_DEFS = [
        { key: "concept", label: "Concept" },
        { key: "race", label: "Race" },
        { key: "ability", label: "Ability Scores" },
        { key: "attributes", label: "Attributes" },
        { key: "culture", label: "Culture" },
        { key: "life", label: "Life Events" },
        { key: "career", label: "Career" },
        { key: "skillPoints", label: "Skill Points" },
        { key: "rounding", label: "Rounding Out" },
        { key: "equip", label: "Equip" },
        { key: "talents", label: "Talents" },
        { key: "personality", label: "Personality" },
        { key: "goals", label: "Goals" },
        { key: "status", label: "Status" },
        { key: "review", label: "Review" }
      ];
      this.draft = {
        culture: "Westlands", lang: "Westronne", base: 20, wises: 4, binds: 2,
        boost: { Combat: null, Adventuring: null, Social: null, Lore: null },
        wipe: true, seedNotes: true,
        raceName: RACES[0]?.name || "", careerName: CAREERS[0]?.name || "",
        allocFor: null, alloc: {},
        abilityPicks: [null, null], abilityExpertise: [null, null], abilityTalent: [null, null], abilityDescriptor: [null, null],
        attrSpend: { resolve: 0, initiative: 0, toughness: 0, dt: 0 }, randomizedInit: false, randomizedDT: false,
        cultureBgName: CULTURES[0]?.name || "", cultureBgFor: null, cultureBgPicks: {},
        humanCultureName: "", humanCultureLang: "",
        lifeEvents: { origin: null, youth: null, recent: null },
        sharedHistoryWith: "", sharedHistorySkill: "",
        relationshipNpcs: [],
        roBonusChoice: "talent", roAge: "Adult", roAlloc: {}, roLoreAlloc: {}, roAllocFor: null, roOldExpertiseSkill: "",
        roSavvy: [null, null, null],
        personalityPicks: [], personalityCustom: "",
        goalIndividual: "", goalShared: "",
        useStatus: true
      };
    }

    static get defaultOptions() {
      return foundry.utils.mergeObject(super.defaultOptions, {
        id: "tbe-character-wizard", title: "TBE: Character Wizard",
        width: 620, height: 640, resizable: true, classes: ["tbe-wizard"]
      });
    }

    race() { return RACES.find((r) => r.name === this.draft.raceName) || RACES[0]; }
    career() { return CAREERS.find((c) => c.name === this.draft.careerName) || CAREERS[0]; }
    culture() { return CULTURES.find((c) => c.name === this.draft.cultureBgName) || CULTURES[0]; }

    ensureAlloc() {
      const career = this.career();
      if (this.draft.allocFor === career.name) return;
      this.draft.alloc = evenSplit(career);
      this.draft.allocFor = career.name;
    }
    ensureCulturePicks() {
      const culture = this.culture();
      if (this.draft.cultureBgFor === culture.name) return;
      this.draft.cultureBgPicks = {};
      this.draft.cultureBgFor = culture.name;
    }
    ensureRoAlloc() {
      const key = this.draft.roAge;
      if (this.draft.roAllocFor === key) return;
      this.draft.roAlloc = {}; this.draft.roLoreAlloc = {};
      this.draft.roAllocFor = key;
    }

    async _renderInner() { return $(this._html()); }

    _progressHtml() {
      return '<div style="display:flex;flex-wrap:wrap;gap:2px;margin-bottom:8px;font-size:9px">' +
        this.STEP_DEFS.map((s, i) => '<div style="flex:1 1 auto;min-width:52px;text-align:center;padding:2px 1px;border-radius:3px;' +
          (i === this.step ? "background:#7a6a4f;color:#fff;font-weight:bold" : i < this.step ? "background:#c9bd9e" : "background:#eee;color:#888") +
          '">' + (i + 1) + ". " + s.label + "</div>").join("") + "</div>";
    }

    _footerHtml() {
      const last = this.step === this.STEP_DEFS.length - 1;
      return '<div style="display:flex;justify-content:space-between;margin-top:10px;border-top:1px solid #7a6a4f;padding-top:8px">' +
        '<button type="button" data-action="back"' + (this.step === 0 ? " disabled" : "") + ">&larr; Back</button>" +
        (last ? '<button type="button" data-action="create" style="font-weight:bold">Create Character</button>'
          : '<button type="button" data-action="next">Next &rarr;</button>') + "</div>";
    }

    // ---- step 1: Concept & Starting Skills (p.79-80) ----------------------
    _step_concept() {
      const d = this.draft;
      let boosts = '<div style="font-size:12px;margin-top:8px;margin-bottom:2px">Choose one skill per category to start at 30 (p.80); all others in that category start at the base value below.</div>';
      for (const cat of Object.keys(SKILLS)) {
        const opts = '<option value="">(none)</option>' + SKILLS[cat].map((n) => '<option value="' + n + '"' + (d.boost[cat] === n ? " selected" : "") + '>' + n + "</option>").join("");
        boosts += '<label style="display:inline-block;width:49%">' + cat + " to 30: <select data-boost-cat=\"" + cat + '" style="width:100%">' + opts + "</select></label>";
      }
      return '<label style="display:block">Cultural background (free text, refined on the Culture step): <input type="text" name="culture" value="' + d.culture + '" style="width:100%"></label>' +
        '<label style="display:block">Native language: <input type="text" name="lang" value="' + d.lang + '" style="width:100%"></label>' +
        '<label style="display:block">Base skill value (book default 20): <input type="number" name="base" value="' + d.base + '" style="width:100%"></label>' +
        '<label style="display:block">Blank -wise slots: <input type="number" name="wises" value="' + d.wises + '" min="0" max="12" style="width:100%"></label>' +
        '<label style="display:block">Blank Bind slots: <input type="number" name="binds" value="' + d.binds + '" min="0" max="6" style="width:100%"></label>' +
        boosts;
    }

    // ---- step 2: Choose a Race (p.81) --------------------------------------
    _step_race() {
      const opts = RACES.map((r) => '<option value="' + r.name + '"' + (r.name === this.draft.raceName ? " selected" : "") + '>' + r.name + " (" + r.d100 + ")</option>").join("");
      const r = this.race();
      const summary = r ? '<div style="font-size:12px;margin-top:6px;opacity:.85">Toughness ' + r.toughness + ", Death Threshold " + r.dt + ", Size " + r.size +
        (r.lethalityBonus ? ", Lethality +" + r.lethalityBonus : "") + "." +
        ((r.skillMods || []).length ? "<br>Skill mods: " + r.skillMods.map((m) => m.skill + " " + (m.mod > 0 ? "+" : "") + m.mod).join(", ") : "") +
        ((r.exclusiveTalents || []).length ? "<br>Exclusive Talents: " + r.exclusiveTalents.join(", ") : "") +
        ((r.restrictions || []).length ? "<br>" + r.restrictions.join("<br>") : "") + "</div>" : "";
      const rollRow = '<div style="margin-top:8px"><button type="button" data-action="roll-race">Roll 1d100 for Race</button>' +
        (this.draft.raceRollNote ? '<div style="font-size:11px;opacity:.8;margin-top:4px">' + this.draft.raceRollNote + "</div>" : "") + "</div>";
      const table = rollTableHtml(RACES.map((rr) => ({ range: rr.d100, name: rr.name, hit: rr.name === this.draft.raceName })), "d100");
      return '<label style="display:block">Race: <select name="race" style="width:100%">' + opts + "</select></label>" + summary + rollRow + table;
    }

    // ---- step 3: Choose Ability Scores (p.85-86) ---------------------------
    _step_ability() {
      const d = this.draft;
      let html = '<div style="font-size:12px;margin-bottom:6px">Pick 2 (or roll 1d6 twice). Each: +5 to its listed skills, 1 Expertise level to one of them, one of 3 Talents, one descriptor (usable as a Personality Trait).</div>';
      for (let i = 0; i < 2; i++) {
        const used = d.abilityPicks.filter((_, j) => j !== i);
        const opts = '<option value="">(none)</option>' + ABILITY_SCORES.filter((a) => used.indexOf(a.name) === -1)
          .map((a) => '<option value="' + a.name + '"' + (d.abilityPicks[i] === a.name ? " selected" : "") + '>' + a.name + "</option>").join("");
        html += '<div style="margin-top:8px;border-top:1px solid #7a6a4f;padding-top:6px"><label style="display:block">Score ' + (i + 1) + ': <select data-ability-idx="' + i + '" style="width:100%">' + opts + "</select></label>";
        const score = ABILITY_SCORES.find((a) => a.name === d.abilityPicks[i]);
        if (score) {
          const exOpts = score.skills.map((s) => '<option value="' + s + '"' + (d.abilityExpertise[i] === s ? " selected" : "") + '>' + s + "</option>").join("");
          const talOpts = score.talents.map((t) => '<option value="' + t + '"' + (d.abilityTalent[i] === t ? " selected" : "") + '>' + t + "</option>").join("");
          const descOpts = score.descriptors.map((x) => '<option value="' + x + '"' + (d.abilityDescriptor[i] === x ? " selected" : "") + '>' + x + "</option>").join("");
          html += '<div style="font-size:11px;opacity:.8;margin:2px 0">+5 to: ' + score.skills.join(", ") + "</div>" +
            '<label style="display:inline-block;width:32%">Expertise: <select data-ability-ex="' + i + '" style="width:100%">' + exOpts + "</select></label>" +
            '<label style="display:inline-block;width:32%">Talent: <select data-ability-tal="' + i + '" style="width:100%">' + talOpts + "</select></label>" +
            '<label style="display:inline-block;width:32%">Descriptor: <select data-ability-desc="' + i + '" style="width:100%">' + descOpts + "</select></label>";
        }
        html += "</div>";
      }
      html += '<div style="margin-top:8px"><button type="button" data-action="roll-ability">Roll 1d6 twice</button></div>';
      return html;
    }

    // ---- step 4: Determine Attributes (p.87) -------------------------------
    _step_attributes() {
      const d = this.draft;
      const s = d.attrSpend;
      const spent = TBE.num(s.resolve, 0) + TBE.num(s.initiative, 0) + TBE.num(s.toughness, 0) + TBE.num(s.dt, 0);
      const remaining = 5 - spent;
      const resolve = 10 + 2 * TBE.num(s.resolve, 0);
      const initBase = d.randomizedInit ? TBE.num(d.initRoll, 6) : 10;
      const initiative = initBase + TBE.num(s.initiative, 0);
      const toughness = Math.floor(TBE.num(s.toughness, 0) / 2);
      const dtBase = d.randomizedDT ? TBE.num(d.dtRoll, 15) : 20;
      const dt = d.randomizedDT ? dtBase : dtBase + 2 * TBE.num(s.dt, 0);
      const ll = Math.ceil(dt / 3);
      return '<div style="font-size:12px;margin-bottom:6px">Allocate 5 points among the first four Attributes. Remaining: <b>' + remaining + "</b></div>" +
        '<label style="display:inline-block;width:49%">Max Resolve points (+2 boxes each): <input type="number" min="0" data-attr="resolve" value="' + TBE.num(s.resolve, 0) + '" style="width:60px"></label>' +
        '<label style="display:inline-block;width:49%">Initiative points (+1 each): <input type="number" min="0" data-attr="initiative" value="' + TBE.num(s.initiative, 0) + '" style="width:60px"' + (d.randomizedInit ? " disabled" : "") + "></label>" +
        '<label style="display:inline-block;width:49%">Toughness points (+1 per 2): <input type="number" min="0" data-attr="toughness" value="' + TBE.num(s.toughness, 0) + '" style="width:60px"></label>' +
        '<label style="display:inline-block;width:49%">Death Threshold points (+2 each): <input type="number" min="0" data-attr="dt" value="' + TBE.num(s.dt, 0) + '" style="width:60px"' + (d.randomizedDT ? " disabled" : "") + "></label>" +
        '<div style="font-size:12px;margin-top:8px;opacity:.9">Max Resolve <b>' + resolve + "</b>, Initiative <b>" + (initiative >= 0 ? "+" : "") + initiative + "</b>, Toughness <b>" + toughness + "</b>, Death Threshold <b>" + dt + "</b>, Lethality Level <b>" + ll + "</b></div>" +
        '<div style="margin-top:8px;border-top:1px solid #7a6a4f;padding-top:6px">' +
        '<label style="display:block"><input type="checkbox" data-attr-opt="randomizedInit"' + (d.randomizedInit ? " checked" : "") + '> Randomized Initiative: start 6+1d6 instead of 10' +
        (d.randomizedInit ? ' <button type="button" data-action="roll-init">Roll</button> ' + (d.initRoll ? "(" + d.initRoll + ")" : "") : "") + "</label>" +
        '<label style="display:block"><input type="checkbox" data-attr-opt="randomizedDT"' + (d.randomizedDT ? " checked" : "") + '> Randomized Death Threshold: start 15+2d4 instead of 20, no further DT points' +
        (d.randomizedDT ? ' <button type="button" data-action="roll-dt">Roll</button> ' + (d.dtRoll ? "(" + d.dtRoll + ")" : "") : "") + "</label></div>";
    }

    // ---- step 5: Pick a Cultural Background (p.88-90) ----------------------
    _step_culture() {
      this.ensureCulturePicks();
      const d = this.draft;
      const opts = CULTURES.map((c) => '<option value="' + c.name + '"' + (c.name === d.cultureBgName ? " selected" : "") + '>' + c.name + " (" + c.range + ")</option>").join("");
      const rollRow = '<div style="margin-top:6px"><button type="button" data-action="roll-culture">Roll 1d10 for Culture</button>' +
        (d.cultureRollNote ? '<div style="font-size:11px;opacity:.8;margin-top:4px">' + d.cultureRollNote + "</div>" : "") + "</div>";
      const table = rollTableHtml(CULTURES.map((c) => ({ range: c.range, name: c.name, hit: c.name === d.cultureBgName })), "d10");
      const culture = this.culture();
      let picks = '<div style="font-size:12px;margin-top:8px">' + culture.name + " bonuses &mdash; pick a skill for each:</div>";
      culture.picks.forEach((pick, pi) => {
        const options = resolveOptions(pick.options);
        const already = d.cultureBgPicks[pi] || [];
        for (let slot = 0; slot < pick.count; slot++) {
          const optsHtml = options.map((s) => '<option value="' + s + '"' + (already[slot] === s ? " selected" : "") + '>' + s + "</option>").join("");
          const label = (pick.expertise ? "Expertise: " : "+" + pick.amount + ": ") + (options.length === 1 ? options[0] : "choose");
          picks += '<label style="display:inline-block;width:49%;font-size:12px">' + label + ': <select data-culture-pick="' + pi + '" data-culture-slot="' + slot + '" style="width:100%">' + optsHtml + "</select></label>";
        }
      });
      let humanCulture = "";
      if (this.race().name === "Human") {
        const hOpts = HUMAN_CULTURES.map((h) => '<option value="' + h.range + '"' + (d.humanCultureRange === h.range ? " selected" : "") + '>' + h.name + " (" + h.range + ") — " + h.language + "</option>").join("");
        humanCulture = '<div style="margin-top:8px;border-top:1px solid #7a6a4f;padding-top:6px"><div style="font-size:12px">Human Culture (p.83) sets your native language above.</div>' +
          '<select data-human-culture style="width:100%">' + hOpts + "</select>" +
          '<div style="margin-top:4px"><button type="button" data-action="roll-human-culture">Roll 1d100</button></div>' +
          rollTableHtml(HUMAN_CULTURES.map((h) => ({ range: h.range, name: h.name + " (" + h.language + ")", hit: h.range === d.humanCultureRange })), "d100") + "</div>";
      }
      return '<label style="display:block">Cultural Background: <select name="cultureBg" style="width:100%">' + opts + "</select></label>" + rollRow + table + picks +
        '<label style="display:block;margin-top:8px">Starting Coin: <b>' + culture.silver + "</b> (rolled on Create)</label>" + humanCulture;
    }

    // ---- step 6: Roll for Life Events (p.91-101) ---------------------------
    _step_life() {
      const d = this.draft;
      const section = (key, table, label) => {
        const chosen = d.lifeEvents[key];
        const rows = table.map((e) => ({ range: e.range, name: e.name, hit: chosen && chosen.range === e.range }));
        return '<div style="margin-top:8px;border-top:1px solid #7a6a4f;padding-top:6px"><b>Life Event: ' + label + "</b> " +
          '<button type="button" data-action="roll-life" data-life-key="' + key + '">Roll 1d100</button>' +
          (chosen ? '<div style="font-size:11px;opacity:.85;margin-top:2px">Rolled: <b>' + chosen.name + "</b> (" + chosen.range + ") — look it up and apply its bonus via the Skills tab.</div>" : "") +
          rollTableHtml(rows, "d100") + "</div>";
      };
      const npcRows = d.relationshipNpcs.map((n, i) => "<li>" + n.source + ": " + n.type + (n.name ? " — " + n.name : "") + ' <button type="button" data-action="remove-npc" data-npc-idx="' + i + '">remove</button></li>').join("");
      return '<div style="font-size:12px">Roll once each on Origin, Youth, and Recent. Names only, per the book’s prose bonuses — check the page for the exact skill/amount.</div>' +
        section("origin", LIFE_EVENTS.origin, "Origin") + section("youth", LIFE_EVENTS.youth, "Youth") + section("recent", LIFE_EVENTS.recent, "Recent") +
        '<div style="margin-top:8px;border-top:1px solid #7a6a4f;padding-top:6px"><b>Shared History</b> (p.94, optional, with another PC)<br>' +
        '<label style="display:inline-block;width:49%">With: <input type="text" name="sharedWith" value="' + d.sharedHistoryWith + '" style="width:100%"></label>' +
        '<label style="display:inline-block;width:49%">Skill (+5 to you): <select name="sharedSkill" style="width:100%"><option value="">(none)</option>' +
        SKILL_ALL.map((s) => '<option value="' + s + '"' + (d.sharedHistorySkill === s ? " selected" : "") + '>' + s + "</option>").join("") + "</select></label></div>" +
        '<div style="margin-top:8px;border-top:1px solid #7a6a4f;padding-top:6px"><b>Relationship NPCs</b> (p.91, up to one per Life Event, roll 1d4)<br>' +
        '<button type="button" data-action="roll-npc">Roll 1d4 for a new Relationship NPC</button>' +
        (npcRows ? "<ul>" + npcRows + "</ul>" : "") + "</div>";
    }

    // ---- step 7: Select a Previous Career (p.102) --------------------------
    _step_career() {
      const opts = CAREERS.map((c) => '<option value="' + c.name + '"' + (c.name === this.draft.careerName ? " selected" : "") + '>' + c.name + "</option>").join("");
      const c = this.career();
      const poolsTxt = Object.entries(c.pools || {}).filter(([, v]) => v).map(([k, v]) => k + " " + v).join(", ");
      const summary = '<div style="font-size:12px;margin-top:6px;opacity:.85">Pools: ' + poolsTxt +
        (c.silver ? "<br>Silver: " + c.silver : "") + (c.talents ? "<br>Talents: " + c.talents : "") + "</div>";
      const rollRow = '<div style="margin-top:8px"><button type="button" data-action="roll-career">Roll 1d10 for Career</button>' +
        (this.draft.careerRollNote ? '<div style="font-size:11px;opacity:.8;margin-top:4px">' + this.draft.careerRollNote + "</div>" : "") + "</div>";
      const table = rollTableHtml(CAREERS.map((cc) => ({ range: String(cc.d10), name: cc.name, hit: cc.name === this.draft.careerName })), "d10");
      return '<label style="display:block">Previous Career: <select name="career" style="width:100%">' + opts + "</select></label>" + summary + rollRow + table;
    }

    // ---- step 7 continued: Career Skill Points ----------------------------
    _step_skillPoints() {
      this.ensureAlloc();
      const career = this.career();
      const cats = poolCats(career);
      if (!cats.length) return '<div style="font-size:12px;opacity:.8">' + career.name + " has no free skill-point pools to spend (a Magic pool, if any, is assigned by hand to Bind skills afterward).</div>";
      let html = '<div style="font-size:12px;margin-bottom:6px">Edit any field. Each skill caps at ' + CHARGEN_SKILL_CAP + " during creation. Skill points cannot be transferred between categories (p.102).</div>";
      for (const [cat, pool] of cats) {
        const names = SKILLS[cat];
        let spent = 0;
        names.forEach((n, idx) => { spent += TBE.num(this.draft.alloc[cat + "_" + idx], 0); });
        html += '<div style="font-weight:bold;margin-top:6px">' + cat + " &mdash; " + spent + " / " + pool + " spent</div>";
        names.forEach((n, idx) => {
          html += '<label style="display:inline-block;width:49%">' + n + ': <input type="number" class="tbe-alloc" data-cat="' + cat + '" data-idx="' + idx +
            '" value="' + TBE.num(this.draft.alloc[cat + "_" + idx], 0) + '" style="width:50px"></label>';
        });
      }
      return html;
    }

    // ---- step 8: Rounding Out (p.108) --------------------------------------
    _step_rounding() {
      this.ensureRoAlloc();
      const d = this.draft;
      const age = ROUNDING_OUT_AGES.find((a) => a.key === d.roAge) || ROUNDING_OUT_AGES[1];
      const bonusRadio = ["talent", "status", "money"].map((v) =>
        '<label style="display:block"><input type="radio" name="roBonus" value="' + v + '"' + (d.roBonusChoice === v ? " checked" : "") + "> " +
        (v === "talent" ? "Take any one Talent you meet the requirements for (pick it later via TBE: Talents)" : v === "status" ? "+1 Status" : "+100 sp") + "</label>").join("");
      const ageRadio = ROUNDING_OUT_AGES.map((a) =>
        '<label style="display:block"><input type="radio" name="roAge" value="' + a.key + '"' + (d.roAge === a.key ? " checked" : "") + "> <b>" + a.key + "</b>: " +
        [a.endurance ? (a.endurance > 0 ? "+" : "") + a.endurance + " Endurance" : "", a.dt ? (a.dt > 0 ? "+" : "") + a.dt + " Death Threshold" : "",
          a.lorePoints ? a.lorePoints + " bonus points (Lore only)" : "", a.anyPoints + " bonus points (any category)", a.expertise ? "+1 Expertise (any applicable skill)" : ""]
          .filter(Boolean).join(", ") + "</label>").join("");
      const allocGrid = (pool, obj, filterCat) => {
        let spent = 0;
        for (const v of Object.values(obj)) spent += TBE.num(v, 0);
        let h = '<div style="font-size:12px;margin:4px 0">' + spent + " / " + pool + " spent" + (filterCat ? " (Lore only)" : "") + "</div>";
        const cats = filterCat ? [filterCat] : Object.keys(SKILLS);
        for (const cat of cats) {
          h += '<div style="font-size:11px;opacity:.8;margin-top:2px">' + cat + "</div>";
          for (const n of SKILLS[cat]) {
            h += '<label style="display:inline-block;width:49%">' + n + ': <input type="number" class="' + (filterCat ? "tbe-ro-lore" : "tbe-ro-any") + '" data-sk="' + n + '" value="' + TBE.num(obj[n], 0) + '" style="width:50px"></label>';
          }
        }
        return h;
      };
      const savvyOpts = (i) => '<option value="">(none)</option>' + SKILL_ALL.map((s) => '<option value="' + s + '"' + (d.roSavvy[i] === s ? " selected" : "") + '>' + s + "</option>").join("");
      return '<div style="font-size:12px;margin-bottom:4px"><b>1. Bonus</b></div>' + bonusRadio +
        '<div style="font-size:12px;margin:8px 0 4px"><b>2. Age</b></div>' + ageRadio +
        (age.expertise ? '<label style="display:block;margin-top:4px">Old’s bonus Expertise skill: <select name="roOldEx" style="width:100%"><option value="">(none)</option>' +
          SKILL_ALL.map((s) => '<option value="' + s + '"' + (d.roOldExpertiseSkill === s ? " selected" : "") + '>' + s + "</option>").join("") + "</select></label>" : "") +
        (age.lorePoints ? '<div style="margin-top:8px;border-top:1px solid #7a6a4f;padding-top:4px">' + allocGrid(age.lorePoints, d.roLoreAlloc, "Lore") + "</div>" : "") +
        '<div style="margin-top:8px;border-top:1px solid #7a6a4f;padding-top:4px">' + allocGrid(age.anyPoints, d.roAlloc, null) + "</div>" +
        '<div style="font-size:12px;margin:8px 0 4px;border-top:1px solid #7a6a4f;padding-top:6px"><b>3. Bonus Savvy Skills</b> (pick 3, not Piety or a Strand)</div>' +
        [0, 1, 2].map((i) => '<label style="display:inline-block;width:32%">Savvy ' + (i + 1) + ': <select data-savvy="' + i + '" style="width:100%">' + savvyOpts(i) + "</select></label>").join("");
    }

    // ---- step 9: Equip Your Character (p.109) ------------------------------
    _step_equip() {
      return '<div style="font-size:12px">' +
        "<div>1. Starting Weapon: a <b>Dagger</b> (added from the compendium on Create).</div>" +
        "<div>2. Starting Armor: roll 1d3+1 pieces on Create (train permitting) &mdash; count reported, buy them on the Gear tab.</div>" +
        "<div>3. Starting Coin: 2d4&times;50 sp rolled on Create, on top of career and culture silver.</div>" +
        "<div>4-5. Weapon/Armor stats and Initiative penalty: fill in as you buy armor (see Ch.9 - Equipment).</div>" +
        "<div>6. Supply Dice: all four (Gear/Ammo/Rations/Medical) set to d12 on Create.</div></div>";
    }

    // ---- Talents preview (auto-granted from Race/Career/Ability Scores) ---
    _step_talents() {
      const race = this.race(), career = this.career();
      const { wanted, careerTalentText } = computeTalents(race, career);
      const d = this.draft;
      (d.abilityTalent || []).forEach((t) => { if (t) wanted.push({ name: t, why: "Ability Score" }); });
      if (d.roBonusChoice === "talent") wanted.push({ name: "(Rounding Out bonus Talent — pick via TBE: Talents)", why: "Rounding Out", skip: true });
      const { talentPayload, notesOut } = resolveTalentPayload(wanted.filter((w) => !w.skip), race, career);
      return '<div style="font-size:12px">Granted automatically:</div>' +
        (talentPayload.length ? "<ul>" + talentPayload.map((t) => "<li>" + t.name + (t.system.ranks > 1 ? " &times;" + t.system.ranks : "") + "</li>").join("") + "</ul>" : '<div style="font-size:12px;opacity:.7">None named outright.</div>') +
        (d.roBonusChoice === "talent" ? '<div style="font-size:11px;opacity:.8">Plus your Rounding Out bonus Talent (pick with TBE: Talents afterward).</div>' : "") +
        '<div style="font-size:11px;opacity:.75">Career Talent text: ' + careerTalentText + "</div>" +
        (notesOut.length ? '<div style="font-size:11px;opacity:.75;margin-top:4px">' + notesOut.join("<br>") + "</div>" : "") +
        '<div style="font-size:11px;opacity:.7;margin-top:6px">Pick any extra/custom Talent slots with <b>TBE: Talents</b> after this wizard finishes.</div>';
    }

    // ---- step 10: Assign Personality Traits (p.109-110) --------------------
    _step_personality() {
      const d = this.draft;
      const boxes = PERSONALITY_TRAITS.map((t) => '<label style="display:inline-block;width:32%;font-size:12px"><input type="checkbox" class="tbe-trait" value="' + t + '"' +
        (d.personalityPicks.indexOf(t) > -1 ? " checked" : "") + "> " + t + "</label>").join("");
      return '<div style="font-size:12px;margin-bottom:6px">Choose two or three (or write your own below).</div>' + boxes +
        '<label style="display:block;margin-top:8px">Custom traits (comma-separated): <input type="text" name="personalityCustom" value="' + d.personalityCustom + '" style="width:100%"></label>';
    }

    // ---- step 11: Create Character Goals -----------------------------------
    _step_goals() {
      const d = this.draft;
      return '<label style="display:block">Individual Goal: <textarea name="goalIndividual" rows="2" style="width:100%">' + d.goalIndividual + "</textarea></label>" +
        '<label style="display:block;margin-top:6px">Shared/Party Goal: <textarea name="goalShared" rows="2" style="width:100%">' + d.goalShared + "</textarea></label>" +
        '<div style="font-size:11px;opacity:.7;margin-top:6px">It’s fine to leave these blank and discover them in play (p.111).</div>';
    }

    // ---- step 12: Status (Optional, p.114) ---------------------------------
    _step_status() {
      const d = this.draft;
      return '<label style="display:block"><input type="checkbox" name="useStatus"' + (d.useStatus ? " checked" : "") + "> This table uses the optional Status rules</label>" +
        '<div style="font-size:11px;opacity:.75;margin-top:6px">Status starts at 0. Several earlier steps offered "+1 Status" instead of a skill bonus — if you took one, add it to Status on the Overview tab by hand after this wizard finishes.</div>';
    }

    // ---- Review & Create ----------------------------------------------------
    _step_review() {
      const { values, spent, raceApplied, abilityApplied, cultureApplied, roApplied, race, career, age } = computeSkillValues(this.draft);
      const { wanted } = computeTalents(race, career);
      const d = this.draft;
      d.abilityTalent.forEach((t) => { if (t) wanted.push({ name: t, why: "Ability Score" }); });
      const { talentPayload } = resolveTalentPayload(wanted, race, career);
      return '<div style="font-size:12px">' +
        "<div><b>" + race.name + "</b> " + career.name + ", " + (d.cultureBgName || "") + ", native " + d.lang + ", " + (d.roAge || "Adult") + "</div>" +
        "<div>Skill points: " + spent.join(", ") + "</div>" +
        (raceApplied.length ? "<div>Race: " + raceApplied.join(", ") + "</div>" : "") +
        (abilityApplied.length ? "<div>Ability Scores: " + abilityApplied.join("; ") + "</div>" : "") +
        (cultureApplied.length ? "<div>Culture: " + cultureApplied.join(", ") + "</div>" : "") +
        (roApplied.length ? "<div>Rounding Out: " + roApplied.join(", ") + "</div>" : "") +
        "<div>Talents to grant: " + (talentPayload.map((t) => t.name).join(", ") || "none") + "</div>" +
        "<div>Life Events: " + ["origin", "youth", "recent"].map((k) => d.lifeEvents[k]?.name).filter(Boolean).join(", ") + "</div>" +
        "</div>" +
        '<label style="display:block;margin-top:8px"><input type="checkbox" name="wipe"' + (d.wipe ? " checked" : "") + "> Remove the actor's existing skills and Talents first</label>" +
        '<label style="display:block"><input type="checkbox" name="seedNotes"' + (d.seedNotes ? " checked" : "") + "> Seed the Notes tab</label>" +
        '<div style="font-size:11px;opacity:.7;margin-top:6px">Nothing is written to the actor until you click Create Character.</div>';
    }

    _html() {
      const key = this.STEP_DEFS[this.step].key;
      const body = this["_step_" + key].call(this);
      return '<form autocomplete="off" style="font-size:13px;padding:4px">' + this._progressHtml() +
        '<div style="margin-bottom:6px">Target: <b>' + this.actor.name + "</b></div>" +
        '<div class="tbe-step-body" style="max-height:420px;overflow-y:auto;padding-right:4px">' + body + "</div>" + this._footerHtml() + "</form>";
    }

    _readCurrentStep(root) {
      const g = (sel) => root.querySelector(sel);
      const key = this.STEP_DEFS[this.step].key;
      const d = this.draft;
      if (key === "concept") {
        d.culture = g('[name="culture"]')?.value ?? d.culture;
        d.lang = g('[name="lang"]')?.value ?? d.lang;
        d.base = TBE.num(g('[name="base"]')?.value, d.base);
        d.wises = TBE.num(g('[name="wises"]')?.value, d.wises);
        d.binds = TBE.num(g('[name="binds"]')?.value, d.binds);
        root.querySelectorAll("[data-boost-cat]").forEach((sel) => { d.boost[sel.dataset.boostCat] = sel.value || null; });
      } else if (key === "race") {
        d.raceName = g('[name="race"]')?.value ?? d.raceName;
      } else if (key === "ability") {
        root.querySelectorAll("[data-ability-idx]").forEach((sel) => { d.abilityPicks[Number(sel.dataset.abilityIdx)] = sel.value || null; });
        root.querySelectorAll("[data-ability-ex]").forEach((sel) => { d.abilityExpertise[Number(sel.dataset.abilityEx)] = sel.value || null; });
        root.querySelectorAll("[data-ability-tal]").forEach((sel) => { d.abilityTalent[Number(sel.dataset.abilityTal)] = sel.value || null; });
        root.querySelectorAll("[data-ability-desc]").forEach((sel) => { d.abilityDescriptor[Number(sel.dataset.abilityDesc)] = sel.value || null; });
      } else if (key === "attributes") {
        root.querySelectorAll("[data-attr]").forEach((inp) => { d.attrSpend[inp.dataset.attr] = TBE.num(inp.value, 0); });
        root.querySelectorAll("[data-attr-opt]").forEach((inp) => { d[inp.dataset.attrOpt] = !!inp.checked; });
      } else if (key === "culture") {
        d.cultureBgName = g('[name="cultureBg"]')?.value ?? d.cultureBgName;
        root.querySelectorAll("[data-culture-pick]").forEach((sel) => {
          const pi = sel.dataset.culturePick, slot = Number(sel.dataset.cultureSlot);
          if (!d.cultureBgPicks[pi]) d.cultureBgPicks[pi] = [];
          d.cultureBgPicks[pi][slot] = sel.value || null;
        });
        const hc = g("[data-human-culture]");
        if (hc) { d.humanCultureRange = hc.value || null; const rec = HUMAN_CULTURES.find((h) => h.range === hc.value); if (rec) d.humanCultureLang = rec.language.split(" or ")[0]; }
      } else if (key === "life") {
        d.sharedHistoryWith = g('[name="sharedWith"]')?.value ?? d.sharedHistoryWith;
        d.sharedHistorySkill = g('[name="sharedSkill"]')?.value ?? d.sharedHistorySkill;
      } else if (key === "career") {
        d.careerName = g('[name="career"]')?.value ?? d.careerName;
      } else if (key === "skillPoints") {
        root.querySelectorAll(".tbe-alloc").forEach((inp) => { d.alloc[inp.dataset.cat + "_" + inp.dataset.idx] = TBE.num(inp.value, 0); });
      } else if (key === "rounding") {
        const bonus = root.querySelector('input[name="roBonus"]:checked'); if (bonus) d.roBonusChoice = bonus.value;
        const age = root.querySelector('input[name="roAge"]:checked'); if (age) d.roAge = age.value;
        d.roOldExpertiseSkill = g('[name="roOldEx"]')?.value ?? d.roOldExpertiseSkill;
        root.querySelectorAll(".tbe-ro-any").forEach((inp) => { d.roAlloc[inp.dataset.sk] = TBE.num(inp.value, 0); });
        root.querySelectorAll(".tbe-ro-lore").forEach((inp) => { d.roLoreAlloc[inp.dataset.sk] = TBE.num(inp.value, 0); });
        root.querySelectorAll("[data-savvy]").forEach((sel) => { d.roSavvy[Number(sel.dataset.savvy)] = sel.value || null; });
      } else if (key === "personality") {
        d.personalityPicks = Array.from(root.querySelectorAll(".tbe-trait:checked")).map((el) => el.value);
        d.personalityCustom = g('[name="personalityCustom"]')?.value ?? d.personalityCustom;
      } else if (key === "goals") {
        d.goalIndividual = g('[name="goalIndividual"]')?.value ?? d.goalIndividual;
        d.goalShared = g('[name="goalShared"]')?.value ?? d.goalShared;
      } else if (key === "status") {
        d.useStatus = !!g('[name="useStatus"]')?.checked;
      } else if (key === "review") {
        d.wipe = !!g('[name="wipe"]')?.checked;
        d.seedNotes = !!g('[name="seedNotes"]')?.checked;
      }
    }

    activateListeners(html) {
      super.activateListeners(html);
      const root = (html[0] ?? html);
      root.querySelectorAll("[data-action]").forEach((btn) => {
        btn.addEventListener("click", async (ev) => {
          const action = ev.currentTarget.dataset.action;
          this._readCurrentStep(root);
          const d = this.draft;
          if (action === "back") { this.step = Math.max(0, this.step - 1); this.render(true); }
          else if (action === "next") { this.step = Math.min(this.STEP_DEFS.length - 1, this.step + 1); this.render(true); }
          else if (action === "roll-race") {
            const roll = await new Roll("1d100").evaluate();
            const picked = raceForRoll(roll.total);
            if (picked) { d.raceName = picked.name; d.raceRollNote = "Rolled 1d100: " + TBE.face(roll.total) + " → " + picked.name; await TBE.say(TBE.card("TBE Character Wizard — Race Roll", "<div>" + this.actor.name + ": 1d100 → " + TBE.face(roll.total) + " (" + picked.name + ")</div>"), [roll]); }
            else d.raceRollNote = "Rolled 1d100: " + TBE.face(roll.total) + " — no race matched, pick by hand.";
            this.render(true);
          }
          else if (action === "roll-ability") {
            const r1 = await new Roll("1d6").evaluate(), r2 = await new Roll("1d6").evaluate();
            const idx = (n) => Math.max(0, Math.min(ABILITY_SCORES.length - 1, n - 1));
            d.abilityPicks[0] = ABILITY_SCORES[idx(r1.total)]?.name || null;
            d.abilityPicks[1] = r2.total === r1.total ? (ABILITY_SCORES[(idx(r2.total) + 1) % ABILITY_SCORES.length]?.name || null) : (ABILITY_SCORES[idx(r2.total)]?.name || null);
            await TBE.say(TBE.card("TBE Character Wizard — Ability Scores", "<div>" + this.actor.name + ": 1d6+1d6 → " + d.abilityPicks.join(", ") + "</div>"), [r1, r2]);
            this.render(true);
          }
          else if (action === "roll-init") { const r = await new Roll("1d6").evaluate(); d.initRoll = 6 + r.total; await TBE.say(TBE.card("TBE Character Wizard — Randomized Initiative", "<div>" + this.actor.name + ": 6+1d6 → " + d.initRoll + "</div>"), [r]); this.render(true); }
          else if (action === "roll-dt") { const r = await new Roll("2d4").evaluate(); d.dtRoll = 15 + r.total; await TBE.say(TBE.card("TBE Character Wizard — Randomized Death Threshold", "<div>" + this.actor.name + ": 15+2d4 → " + d.dtRoll + "</div>"), [r]); this.render(true); }
          else if (action === "roll-culture") {
            const roll = await new Roll("1d10").evaluate();
            const picked = cultureBgForRoll(roll.total);
            if (picked) { d.cultureBgName = picked.name; d.cultureRollNote = "Rolled 1d10: " + roll.total + " → " + picked.name; await TBE.say(TBE.card("TBE Character Wizard — Culture Roll", "<div>" + this.actor.name + ": 1d10 → " + roll.total + " (" + picked.name + ")</div>"), [roll]); }
            else d.cultureRollNote = "Rolled 1d10: " + roll.total + " — no culture matched, pick by hand.";
            this.render(true);
          }
          else if (action === "roll-human-culture") {
            const roll = await new Roll("1d100").evaluate();
            const picked = humanCultureForRoll(roll.total);
            if (picked) { d.humanCultureRange = picked.range; d.humanCultureLang = picked.language.split(" or ")[0]; await TBE.say(TBE.card("TBE Character Wizard — Human Culture Roll", "<div>" + this.actor.name + ": 1d100 → " + TBE.face(roll.total) + " (" + picked.name + ", " + picked.language + ")</div>"), [roll]); }
            this.render(true);
          }
          else if (action === "roll-life") {
            const key = ev.currentTarget.dataset.lifeKey;
            const table = LIFE_EVENTS[key];
            const roll = await new Roll("1d100").evaluate();
            const picked = lifeEventForRoll(table, roll.total);
            if (picked) { d.lifeEvents[key] = picked; await TBE.say(TBE.card("TBE Character Wizard — Life Event: " + key, "<div>" + this.actor.name + ": 1d100 → " + TBE.face(roll.total) + " (" + picked.name + ")</div>"), [roll]); }
            this.render(true);
          }
          else if (action === "roll-npc") {
            const roll = await new Roll("1d4").evaluate();
            const type = RELATIONSHIP_TYPES.find((t) => t.d4 === roll.total)?.name || "Friend";
            d.relationshipNpcs.push({ source: "life event", type, name: "" });
            await TBE.say(TBE.card("TBE Character Wizard — Relationship NPC", "<div>" + this.actor.name + ": 1d4 → " + roll.total + " (" + type + ")</div>"), [roll]);
            this.render(true);
          }
          else if (action === "remove-npc") { d.relationshipNpcs.splice(Number(ev.currentTarget.dataset.npcIdx), 1); this.render(true); }
          else if (action === "roll-career") {
            const roll = await new Roll("1d10").evaluate();
            const picked = careerForRoll(roll.total);
            if (picked) { d.careerName = picked.name; d.careerRollNote = "Rolled 1d10: " + roll.total + " → " + picked.name; await TBE.say(TBE.card("TBE Character Wizard — Career Roll", "<div>" + this.actor.name + ": 1d10 → " + roll.total + " (" + picked.name + ")</div>"), [roll]); }
            else d.careerRollNote = "Rolled 1d10: " + roll.total + " — no career matched, pick by hand.";
            this.render(true);
          }
          else if (action === "create") {
            btn.disabled = true;
            try { await this.commit(); this.close(); }
            catch (err) { console.error("TBE | wizard commit failed", err); ui.notifications?.error("TBE: character creation failed, see console (F12)."); btn.disabled = false; }
          }
        });
      });
    }

    /* One atomic commit at the end. */
    async commit() {
      const d = this.draft;
      const native = (d.humanCultureLang || d.lang || "Westronne").trim();
      const rolls = [];
      let notesOut = [];
      let removed = 0;

      if (d.wipe) {
        const ids = this.actor.items.filter((i) => i.type === "skill" || i.type === "talent" || i.type === "weapon").map((i) => i.id);
        if (ids.length) { await this.actor.deleteEmbeddedDocuments("Item", ids); removed = ids.length; }
      }

      const { values, spent, raceApplied, abilityApplied, cultureApplied, roApplied, notesOut: calcNotes, race, career, age } = computeSkillValues(d);
      notesOut = notesOut.concat(calcNotes);

      const mk = (group, name, value, fighting, extra) => ({ name, type: "skill", system: Object.assign({ group, value: Math.max(0, TBE.num(value, 0)), fighting: !!fighting }, extra || {}) });
      const payload = Object.entries(values).map(([name, v]) => mk(v.group, name, v.value, v.fighting, { expertise: v.expertise || 0, savvy: !!v.savvy }));
      for (const l of race.languages || []) {
        const nm = /cultural|their cultural/i.test(l.name) ? native : l.name;
        payload.push(mk("Language", nm, l.value));
      }
      const culture = this.culture();
      if (culture && culture.extraLanguage) payload.push(mk("Language", "Cultural extra Language", culture.extraLanguage));
      if (this.race().name === "Human" && d.humanCultureRange === "59-64") {
        payload.push(mk("Language", "Low Vestrian (Old Vestrian)", 70));
        payload.push(mk("Language", "High Vestrian", 20));
        notesOut.push("Old Vestrian: Low Vestrian 70 / High Vestrian 20 were added instead of a single cultural language.");
      }
      for (const sk of race.startingSkills || []) payload.push(mk("Lore", sk.name, sk.value));
      const wises = Math.max(0, TBE.num(d.wises, 4));
      for (let i = 0; i < wises; i++) payload.push(mk("Wise", "Wise: subject " + (i + 1), TBE.num(d.base, 20)));
      const binds = Math.max(0, TBE.num(d.binds, 2));
      for (let i = 0; i < binds; i++) payload.push(mk("Bind", "Bind: name it " + (i + 1), 0));
      payload.push(mk("Bind", "Strand, name it", 0));
      payload.push(mk("Lore", "Piety", career.name === "Godbound" ? 20 : 0));
      for (const [count, value] of (career.customs || [])) {
        for (let i = 0; i < count; i++) payload.push(mk("Wise", "Career wise/Language " + (i + 1), value));
      }

      let made = 0;
      try { made = (await this.actor.createEmbeddedDocuments("Item", payload)).length; }
      catch (err) { console.error("TBE | skill creation failed", err); ui.notifications?.error("TBE: could not create skill items, see console (F12)."); }

      // Shared History (+5 to a named skill on THIS actor; the other PC's
      // half of it is out of scope for a single-actor wizard).
      if (d.sharedHistorySkill) {
        const item = this.actor.items.find((i) => i.type === "skill" && i.name === d.sharedHistorySkill);
        if (item) { try { await item.update({ "system.value": Math.min(CHARGEN_SKILL_CAP, item.system.value + 5) }); } catch (err) { console.warn("TBE | shared history update failed", err); } }
        notesOut.push("Shared History with " + (d.sharedHistoryWith || "another PC") + ": +5 " + d.sharedHistorySkill + ".");
      }

      const { wanted } = computeTalents(race, career);
      (d.abilityTalent || []).forEach((t) => { if (t) wanted.push({ name: t, why: "Ability Score" }); });
      const { talentPayload, notesOut: talentNotes } = resolveTalentPayload(wanted, race, career);
      notesOut = notesOut.concat(talentNotes);
      if (talentPayload.length) {
        try { await this.actor.createEmbeddedDocuments("Item", talentPayload); }
        catch (err) { console.error("TBE | talent creation failed", err); }
      }

      // Equip Your Character: Dagger from the compendium, armor-piece count
      // and starting coin rolled and reported (actual shopping stays manual).
      try {
        const pack = game.packs.get("the-broken-empires.tbe-equipment");
        const daggerDoc = pack ? (await pack.getDocuments({ name: "Dagger" }))[0] : null;
        if (daggerDoc) await this.actor.createEmbeddedDocuments("Item", [daggerDoc.toObject()]);
        else notesOut.push("Starting Dagger: compendium not found, add one by hand.");
      } catch (err) { console.warn("TBE | dagger add failed", err); }
      const armorRoll = await new Roll("1d3+1").evaluate();
      rolls.push(armorRoll);
      const equipCoinRoll = await new Roll("2d4*50").evaluate();
      rolls.push(equipCoinRoll);

      const s = d.attrSpend;
      const resolveMax = 10 + 2 * TBE.num(s.resolve, 0);
      const initBase = d.randomizedInit ? TBE.num(d.initRoll, 6) : 10;
      const initiative = initBase + TBE.num(s.initiative, 0);
      const toughness = Math.floor(TBE.num(s.toughness, 0) / 2) + (race.toughness || 0);
      const dtBase = d.randomizedDT ? TBE.num(d.dtRoll, 15) : 20;
      const dt = (d.randomizedDT ? dtBase : dtBase + 2 * TBE.num(s.dt, 0)) + (age?.dt || 0);

      const careerSilverRoll = career.silver ? await new Roll(career.silver).evaluate() : null;
      if (careerSilverRoll) rolls.push(careerSilverRoll);
      const cultureSilverRoll = culture?.silver ? await new Roll(culture.silver).evaluate() : null;
      if (cultureSilverRoll) rolls.push(cultureSilverRoll);
      const totalSilver = (careerSilverRoll ? careerSilverRoll.total : 0) + (cultureSilverRoll ? cultureSilverRoll.total : 0) + equipCoinRoll.total +
        (d.roBonusChoice === "money" ? 100 : 0);

      const update = {
        "system.race": race.name, "system.career": career.name, "system.culture": (d.cultureBgName || d.culture || "").trim(),
        "system.size": race.size, "system.toughness": toughness,
        "system.deathThreshold.value": dt, "system.deathThreshold.max": dt,
        "system.resolve.value": resolveMax, "system.resolve.max": resolveMax,
        "system.initiative": initiative,
        "system.lethalityBonus": race.lethalityBonus || 0, "system.fatigue": 0,
        "system.silver": totalSilver,
        "system.status": d.roBonusChoice === "status" ? 1 : 0,
        "system.supply.gear": 12, "system.supply.ammo": 12, "system.supply.rations": 12, "system.supply.medical": 12
      };
      try { await this.actor.update(update); } catch (err) { console.warn("TBE | could not write vitals", err); }

      if (race.toughnessCap !== null && race.toughnessCap !== undefined) notesOut.push(race.name + " can never exceed Toughness " + race.toughnessCap + ".");
      for (const r of race.restrictions || []) notesOut.push(r);
      if (race.savvy && race.savvy.length) notesOut.push("Bonus Savvy skill (race): " + race.savvy.join(race.savvy.length > 2 ? ", or " : " / ") + ".");
      if (race.bonus) notesOut.push(race.bonus);
      for (const [count, value] of (career.customs || [])) notesOut.push("Rename the " + count + " career -wise/Language slot(s), each at " + value + ".");
      notesOut.push("Starting armor: roll of " + armorRoll.total + " piece(s), buy on the Gear tab (training permitting), then set their Initiative penalty by hand.");
      if (["origin", "youth", "recent"].some((k) => d.lifeEvents[k])) {
        notesOut.push("Life Events rolled: " + ["origin", "youth", "recent"].map((k) => d.lifeEvents[k] ? k + " → " + d.lifeEvents[k].name : null).filter(Boolean).join(", ") + " — apply each one's skill bonus by hand from the book.");
      }
      if (d.relationshipNpcs.length) notesOut.push("Relationship NPCs: " + d.relationshipNpcs.map((n) => n.type + (n.name ? " (" + n.name + ")" : "")).join(", ") + ".");
      const personality = d.personalityPicks.concat((d.personalityCustom || "").split(",").map((s) => s.trim()).filter(Boolean));
      if (personality.length) notesOut.push("Personality Traits: " + personality.join(", ") + ".");
      if (d.abilityDescriptor.some(Boolean)) notesOut.push("Ability Score descriptors (usable as Personality Traits): " + d.abilityDescriptor.filter(Boolean).join(", ") + ".");
      if (!d.useStatus) notesOut.push("Status rules are off for this table.");

      if (this.actor.type === "character" && d.seedNotes) {
        const html = "<h3>Concept</h3><p>Race: " + race.name + "<br>Cultural background: " + (d.cultureBgName || "") +
          "<br>Previous career: " + career.name + "<br>Concept: </p>" +
          "<h3>Still to decide</h3><ul>" + notesOut.map((n) => "<li>" + n + "</li>").join("") + "</ul>" +
          "<h3>Goals</h3><ul><li>Individual: " + (d.goalIndividual || "") + "</li><li>Shared: " + (d.goalShared || "") + "</li></ul>" +
          "<h3>Personality traits and descriptors</h3><p>" + personality.join(", ") + "</p><h3>Status and relationships</h3><p></p>";
        try { await this.actor.update({ "system.notes": html }); } catch (err) { console.error("TBE | notes seed failed", err); }
      }

      const body = "<div><b>" + this.actor.name + "</b> &mdash; " + race.name + " " + career.name + "</div>" +
        "<div>" + made + " skills created" + (removed ? ", " + removed + " old items removed" : "") + ".</div>" +
        (spent.length ? "<div>Career skill points (spent/pool): " + spent.join(", ") + ".</div>" : "") +
        (raceApplied.length ? "<div>Racial modifiers: " + raceApplied.join(", ") + ".</div>" : "") +
        (abilityApplied.length ? "<div>Ability Scores: " + abilityApplied.join("; ") + ".</div>" : "") +
        (cultureApplied.length ? "<div>Cultural Background: " + cultureApplied.join(", ") + ".</div>" : "") +
        (roApplied.length ? "<div>Rounding Out: " + roApplied.join(", ") + ".</div>" : "") +
        "<div>Toughness <b>" + toughness + "</b>, Death Threshold <b>" + dt + "</b>, Resolve <b>" + resolveMax + "</b>, Initiative <b>" + (initiative >= 0 ? "+" : "") + initiative + "</b>.</div>" +
        (talentPayload.length ? "<div>Talents granted: " + talentPayload.map((t) => t.name + (t.system.ranks > 1 ? " &times;" + t.system.ranks : "")).join(", ") + ".</div>" : "") +
        "<div>Total starting silver: <b>" + totalSilver + " sp</b>.</div>" +
        '<div style="border-top:1px solid #7a6a4f;margin-top:4px;padding-top:4px;font-size:11px;opacity:.85">' +
        notesOut.length + " thing(s) still need your decision, listed on the Notes tab.</div>";
      await TBE.say(TBE.card("TBE Character Built (Wizard)", body), rolls);
    }
  }

  new TBECharacterWizard(actor).render(true);
}
